// `pyfun bundle`: a static web page that runs the compiled program on
// Pyodide. The page and its loader are fixed text around the program's
// file list, assets, entry module, title and page fragment.

use std::path::Path;

/// The loader, split around the file list, the asset list and the entry.
const LOADER_HEAD: &str = r##"// The bundle's loader (`pyfun bundle`, `DESIGN.md` §6 "Browser target"): boots
// Pyodide from its CDN, stages the compiled Python files and any assets into the
// in-browser file system, and runs the entry module. The page's DOM is reachable
// from the program through Pyodide's `js` module (`extern import js`), stdout and
// stderr land in the two `<pre>` elements, and a raised exception prints there
// too. A module script, so top-level `await` is available.
import { loadPyodide } from "https://cdn.jsdelivr.net/pyodide/v314.0.3/full/pyodide.mjs";

const FILES = "##;
const LOADER_FILES_ASSETS: &str = r##";
const ASSETS = "##;
const LOADER_ASSETS_ENTRY: &str = r##";
const ENTRY = "##;
const LOADER_TAIL: &str = r##";

const stdout = document.getElementById("pyfun-stdout");
const stderr = document.getElementById("pyfun-stderr");
const status = document.getElementById("pyfun-status");
const append = (el, text) => {
  el.textContent += text;
};

status.textContent = "loading Python…";
const pyodide = await loadPyodide({
  indexURL: "https://cdn.jsdelivr.net/pyodide/v314.0.3/full/",
  stdout: (line) => append(stdout, line + "\n"),
  stderr: (line) => append(stderr, line + "\n"),
});

// The compiled modules import each other as siblings (`import geometry`), so
// they are staged in the working directory, which is first on `sys.path`.
for (const name of FILES) {
  const source = await (await fetch(new URL(name, import.meta.url))).text();
  pyodide.FS.writeFile(name, source);
}
for (const name of ASSETS) {
  const bytes = new Uint8Array(await (await fetch(new URL(name, import.meta.url))).arrayBuffer());
  pyodide.FS.writeFile(name, bytes);
}
pyodide.runPython("import sys\nif '' not in sys.path: sys.path.insert(0, '')");

status.textContent = "";
try {
  const entry = pyodide.FS.readFile(ENTRY, { encoding: "utf8" });
  await pyodide.runPythonAsync(entry);
} catch (e) {
  append(stderr, String((e && e.message) || e) + "\n");
}
"##;

/// The page, split around the title and the fragment.
const PAGE_HEAD: &str = r##"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>"##;
const PAGE_TITLE_BODY: &str = r##"</title>
  <style>
    body { font: 15px/1.5 system-ui, sans-serif; margin: 2rem auto; max-width: 48rem; padding: 0 1rem; }
    pre { white-space: pre-wrap; word-break: break-word; }
    #pyfun-stderr { color: #b00020; }
    #pyfun-status { color: #666; font-style: italic; }
  </style>
</head>
<body>
"##;
const PAGE_TAIL: &str = r##"
  <p id="pyfun-status"></p>
  <pre id="pyfun-stdout"></pre>
  <pre id="pyfun-stderr"></pre>
  <!-- Generated by `pyfun bundle`: the program runs on Pyodide (CPython in
       WebAssembly), loaded from its CDN on first visit; see pyfun-bundle.js. -->
  <script type="module" src="./pyfun-bundle.js"></script>
</body>
</html>
"##;

struct BundleArgs {
    file: String,
    out: String,
    assets: Vec<String>,
    page: Option<String>,
}

fn parse_args(args: &[String]) -> BundleArgs {
    let mut file: Option<String> = None;
    let mut out: Option<String> = None;
    let mut assets = Vec::new();
    let mut page = None;
    let mut i = 0;
    while i < args.len() {
        let a = args[i].as_str();
        let value = |what: &str| -> String {
            match args.get(i + 1) {
                Some(v) => v.clone(),
                None => crate::fail(&format!("error: `{}` needs {}", a, what)),
            }
        };
        match a {
            "-o" => {
                out = Some(value("a directory"));
                i += 2;
            }
            "--asset" => {
                assets.push(value("a file path"));
                i += 2;
            }
            "--page" => {
                page = Some(value("an HTML file"));
                i += 2;
            }
            _ => {
                if file.is_some() {
                    crate::fail(&format!("error: unexpected argument `{}`", a));
                }
                file = Some(a.to_string());
                i += 1;
            }
        }
    }
    let Some(file) = file else { crate::fail("error: `bundle` needs a file path") };
    let Some(out) = out else { crate::fail("error: `bundle` needs `-o <dir>` (the page's directory)") };
    BundleArgs { file, out, assets, page }
}

/// A JavaScript array of strings.
fn js_list(items: &[String]) -> String {
    let quoted: Vec<String> = items.iter().map(|s| js_string(s)).collect();
    format!("[{}]", quoted.join(", "))
}

fn js_string(s: &str) -> String {
    format!("\"{}\"", s.replace('\\', "\\\\").replace('"', "\\\""))
}

fn html_escape(s: &str) -> String {
    s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;")
}

fn plural(n: usize, one: &str) -> String {
    if n == 1 {
        format!("1 {}", one)
    } else {
        format!("{} {}s", n, one)
    }
}

pub fn cmd_bundle(args: &[String]) {
    let a = parse_args(args);
    let ck = crate::load_checked(&a.file, true);
    let em = crate::project::emit_all(&ck, &crate::project::EmitOpts { py311: false, native: false });
    let project = ck.mods.len() > 1;
    // one module runs as `main.py`; a project keeps its module files
    let files: Vec<(String, String)> = if project { em.files.clone() } else { vec![("main.py".to_string(), em.files[0].1.clone())] };
    let entry = if project { format!("{}.py", crate::project::py_module_of(&ck.mods.last().unwrap().file)) } else { "main.py".to_string() };
    let out = Path::new(&a.out);
    if let Err(e) = std::fs::create_dir_all(out) {
        crate::fail(&format!("error: cannot create {}: {}", a.out, e));
    }
    for (f, text) in &files {
        let p = out.join(f);
        if let Err(e) = std::fs::write(&p, text) {
            crate::fail(&format!("error: cannot write {}: {}", p.display(), e));
        }
    }
    let mut asset_names = Vec::new();
    for asset in &a.assets {
        let name = Path::new(asset).file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_else(|| asset.clone());
        if let Err(e) = std::fs::copy(asset, out.join(&name)) {
            crate::fail(&format!("error: cannot copy {}: {}", asset, e));
        }
        asset_names.push(name);
    }
    let fragment = match &a.page {
        Some(p) => match std::fs::read_to_string(p) {
            Ok(s) => s,
            Err(e) => crate::fail(&format!("error: cannot read {}: {}", p, e)),
        },
        None => String::new(),
    };
    let title = Path::new(&a.file).file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
    let page = format!("{}{}{}{}{}", PAGE_HEAD, html_escape(&title), PAGE_TITLE_BODY, fragment, PAGE_TAIL);
    let names: Vec<String> = files.iter().map(|(f, _)| f.clone()).collect();
    let loader = format!(
        "{}{}{}{}{}{}{}",
        LOADER_HEAD,
        js_list(&names),
        LOADER_FILES_ASSETS,
        js_list(&asset_names),
        LOADER_ASSETS_ENTRY,
        js_string(&entry),
        LOADER_TAIL
    );
    for (f, text) in [("index.html", &page), ("pyfun-bundle.js", &loader)] {
        let p = out.join(f);
        if let Err(e) = std::fs::write(&p, text) {
            crate::fail(&format!("error: cannot write {}: {}", p.display(), e));
        }
    }
    eprintln!(
        "wrote index.html to {} ({}, {}); serve the directory over http and open it",
        a.out,
        plural(files.len(), "module"),
        plural(asset_names.len(), "asset")
    );
}

// ---- `pyfun build --native`: a C extension through mypyc --------------

const MYPYC_FLAGS: &[&str] = &[
    "--allow-redefinition-new",
    "--local-partial-types",
    "--disable-error-code",
    "func-returns-value",
    "--disable-error-code",
    "var-annotated",
    "--disable-error-code",
    "union-attr",
];

/// A single program's module name: its lowercased stem, or a `_pf_` name
/// when that is not a plain identifier.
fn single_module_name(file: &str) -> String {
    let stem = Path::new(file).file_stem().map(|s| s.to_string_lossy().to_lowercase()).unwrap_or_default();
    let plain = !stem.is_empty() && stem.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_') && !stem.starts_with(|c: char| c.is_ascii_digit());
    if plain {
        stem
    } else {
        let s: String = stem.chars().map(|c| if c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_' { c } else { '_' }).collect();
        format!("_pf_{}", s)
    }
}

pub fn cmd_build(args: &[String]) {
    let mut native = false;
    let mut file: Option<String> = None;
    let mut out: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--native" => native = true,
            "-o" => {
                if let Some(v) = args.get(i + 1) {
                    out = Some(v.clone());
                    i += 1;
                }
            }
            a => {
                if file.is_some() {
                    crate::fail(&format!("error: unexpected argument `{}`", a));
                }
                file = Some(a.to_string());
            }
        }
        i += 1;
    }
    if !native {
        crate::fail("error: `build` compiles with mypyc and needs `--native` (pyfun build --native <file> -o <dir>)");
    }
    let Some(file) = file else { crate::fail("error: `build` needs a file path") };
    let Some(out) = out else { crate::fail("error: `build` needs an output directory (-o <dir>)") };
    let ck = crate::load_checked(&file, true);
    let em = crate::project::emit_all(&ck, &crate::project::EmitOpts { py311: false, native: true });
    let project = ck.mods.len() > 1;
    let (files, modules, entry): (Vec<(String, String)>, Vec<String>, String) = if project {
        let modules: Vec<String> = em.files.iter().map(|(f, _)| f.clone()).filter(|f| f != "_pyfun_rt.py").collect();
        let entry = crate::project::py_module_of(&ck.mods.last().unwrap().file);
        (em.files.clone(), modules, entry)
    } else {
        let name = single_module_name(&file);
        let f = format!("{}.py", name);
        (vec![(f.clone(), em.files[0].1.clone())], vec![f], name)
    };
    let dir = Path::new(&out);
    if let Err(e) = std::fs::create_dir_all(dir) {
        crate::fail(&format!("error: cannot create {}: {}", out, e));
    }
    for (f, text) in &files {
        let p = dir.join(f);
        if let Err(e) = std::fs::write(&p, text) {
            crate::fail(&format!("error: cannot write {}: {}", p.display(), e));
        }
    }
    let python = crate::pkg::package_python();
    let status = std::process::Command::new(&python).arg("-m").arg("mypyc").args(MYPYC_FLAGS).args(&modules).current_dir(dir).status();
    match status {
        Ok(s) if s.success() => {}
        Ok(_) => crate::fail("error: mypyc could not build the program (see its output above); it needs `pip install mypy setuptools` and a C compiler"),
        Err(e) => crate::fail(&format!("error: cannot run {}: {}", python, e)),
    }
    // the extension modules replace the Python sources
    for m in &modules {
        let _ = std::fs::remove_file(dir.join(m));
    }
    let main = format!("# Runs the mypyc-compiled Pyfun program `{}`.\nimport {}  # noqa: F401\n", entry, entry);
    if let Err(e) = std::fs::write(dir.join("__main__.py"), main) {
        crate::fail(&format!("error: cannot write {}: {}", dir.join("__main__.py").display(), e));
    }
    println!("built {} natively: run it with `python {}`", file, out);
}
// Façade packages: `pyfun add`, `pyfun install` and `pyfun remove`. A façade
// is a Python package that ships .pyfun files; installing one vendors those
// files under `.pyfun/facades/<package>/` next to pyfun.toml, where module
// lookup finds them, and records the version under [dependencies].

use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

const METADATA_SCRIPT: &str = "import importlib.metadata as m, sys
d = m.distribution(sys.argv[1])
print(d.version)
for f in d.files or []:
    if str(f).endswith('.pyfun'):
        print(d.locate_file(f))
";

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    std::process::exit(1);
}

/// pyfun.toml in the working directory or the nearest parent.
fn find_toml() -> Option<PathBuf> {
    let cwd = std::env::current_dir().ok()?;
    cwd.ancestors().map(|d| d.join("pyfun.toml")).find(|p| p.is_file())
}

/// The façade directories a program at `main` sees: those vendored next to
/// the pyfun.toml found from the program's directory upward.
pub fn facade_dirs(main: &Path) -> Vec<PathBuf> {
    let parent = main.parent().unwrap_or(Path::new(""));
    for dir in parent.ancestors() {
        if dir.join("pyfun.toml").is_file() {
            let mut dirs: Vec<PathBuf> = match std::fs::read_dir(dir.join(".pyfun").join("facades")) {
                Ok(rd) => rd.filter_map(|e| e.ok()).map(|e| e.path()).filter(|p| p.is_dir()).collect(),
                Err(_) => Vec::new(),
            };
            dirs.sort();
            return dirs;
        }
    }
    Vec::new()
}

/// The interpreter for package work: PYFUN_PYTHON, else `python`, else `python3`.
pub fn package_python() -> String {
    match crate::find_python(true) {
        Ok(p) => p,
        Err(_) => fail("no Python interpreter found (set PYFUN_PYTHON)"),
    }
}

fn have_uv() -> bool {
    Command::new("uv")
        .arg("--version")
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

/// The package name a requirement names (`pkg==1.0`, `pkg[extra]` → `pkg`).
fn package_name(spec: &str) -> String {
    let end = spec.find(|c: char| matches!(c, '=' | '<' | '>' | '!' | '~' | '[' | ';' | '@') || c.is_whitespace()).unwrap_or(spec.len());
    let name = &spec[..end];
    if name.is_empty() {
        fail(&format!("cannot read a package name from `{}`", spec));
    }
    name.to_string()
}

/// The normalized name a package's façade directory goes by.
fn normalized(name: &str) -> String {
    name.to_lowercase().split(|c| matches!(c, '-' | '_' | '.')).filter(|s| !s.is_empty()).collect::<Vec<_>>().join("-")
}

// ---- pyfun.toml, edited line by line ------------------------------------

struct Toml {
    path: PathBuf,
    lines: Vec<String>,
}

fn section_of(line: &str) -> Option<String> {
    let t = line.trim();
    if t.starts_with('[') && t.ends_with(']') && t.len() >= 2 {
        Some(t[1..t.len() - 1].trim().to_string())
    } else {
        None
    }
}

/// `key = "value"` (a trailing comment allowed): the key and value.
fn dep_entry(line: &str) -> Option<(String, String)> {
    if line.trim_start().starts_with('#') {
        return None;
    }
    let (k, v) = line.split_once('=')?;
    let k = k.trim();
    let k = if k.len() >= 2 && k.starts_with('"') && k.ends_with('"') { &k[1..k.len() - 1] } else { k };
    let v = v.trim().strip_prefix('"')?;
    let close = v.find('"')?;
    let rest = v[close + 1..].trim();
    if !rest.is_empty() && !rest.starts_with('#') {
        return None;
    }
    Some((k.to_string(), v[..close].to_string()))
}

impl Toml {
    fn load(path: &Path) -> Toml {
        let text = match std::fs::read_to_string(path) {
            Ok(t) => t,
            Err(e) => fail(&format!("cannot read {}: {}", path.display(), e)),
        };
        Toml { path: path.to_path_buf(), lines: text.lines().map(|l| l.to_string()).collect() }
    }

    /// Each dependency entry: (line index, name, version).
    fn deps(&self) -> Vec<(usize, String, String)> {
        let mut out = Vec::new();
        let mut in_deps = false;
        for (i, l) in self.lines.iter().enumerate() {
            if let Some(s) = section_of(l) {
                in_deps = s == "dependencies";
                continue;
            }
            if in_deps {
                if let Some((k, v)) = dep_entry(l) {
                    out.push((i, k, v));
                }
            }
        }
        out
    }

    fn set(&mut self, name: &str, version: &str) {
        let entry = format!("{} = \"{}\"", name, version);
        if let Some((i, _, _)) = self.deps().into_iter().find(|(_, k, _)| k == name) {
            self.lines[i] = entry;
            return;
        }
        // after the last entry of the dependencies section (or its header)
        let mut at: Option<usize> = None;
        let mut in_deps = false;
        for (i, l) in self.lines.iter().enumerate() {
            if let Some(s) = section_of(l) {
                in_deps = s == "dependencies";
                if in_deps {
                    at = Some(i);
                }
                continue;
            }
            let t = l.trim();
            if in_deps && !t.is_empty() && !t.starts_with('#') {
                at = Some(i);
            }
        }
        match at {
            Some(i) => self.lines.insert(i + 1, entry),
            None => {
                if self.lines.last().map_or(false, |l| !l.trim().is_empty()) {
                    self.lines.push(String::new());
                }
                self.lines.push("[dependencies]".to_string());
                self.lines.push(entry);
            }
        }
    }

    fn remove(&mut self, name: &str) -> bool {
        match self.deps().into_iter().find(|(_, k, _)| k == name) {
            Some((i, _, _)) => {
                self.lines.remove(i);
                true
            }
            None => false,
        }
    }

    fn save(&self) {
        let mut text = self.lines.join("\n");
        text.push('\n');
        if let Err(e) = std::fs::write(&self.path, text) {
            fail(&format!("cannot write {}: {}", self.path.display(), e));
        }
    }
}

// ---- installing ----------------------------------------------------------

/// Install `spec`, vendor its .pyfun files and record it.
fn add_one(spec: &str, toml: &mut Toml) {
    let name = package_name(spec);
    let python = package_python();
    let status = if have_uv() {
        Command::new("uv").args(["pip", "install", "--python", &python, spec]).status()
    } else {
        Command::new(&python).args(["-m", "pip", "install", spec]).status()
    };
    match status {
        Ok(s) if s.success() => {}
        Ok(_) => fail(&format!("installing `{}` failed (see the installer's output above)", spec)),
        Err(e) => fail(&format!("cannot run the installer: {}", e)),
    }
    let out = match Command::new(&python).arg("-c").arg(METADATA_SCRIPT).arg(&name).stdin(Stdio::null()).output() {
        Ok(o) => o,
        Err(e) => fail(&format!("cannot run {}: {}", python, e)),
    };
    if !out.status.success() {
        let err = String::from_utf8_lossy(&out.stderr);
        fail(&format!("cannot read the installed metadata of `{}`: {}", name, err.trim_end()));
    }
    let text = String::from_utf8_lossy(&out.stdout).to_string();
    let mut lines = text.lines();
    let version = lines.next().unwrap_or("").trim().to_string();
    let files: Vec<&str> = lines.collect();
    if files.is_empty() {
        fail(&format!("`{}` installed, but it ships no .pyfun files, so it is not a Pyfun façade", name));
    }
    let root = toml.path.parent().map(|p| p.to_path_buf()).unwrap_or_default();
    let dir = root.join(".pyfun").join("facades").join(normalized(&name));
    if dir.exists() {
        let _ = std::fs::remove_dir_all(&dir);
    }
    if let Err(e) = std::fs::create_dir_all(&dir) {
        fail(&format!("cannot create {}: {}", dir.display(), e));
    }
    let mut modules = Vec::new();
    for f in files {
        let src = Path::new(f);
        let Some(fname) = src.file_name() else { fail(&format!("odd façade path {}", f)) };
        if let Err(e) = std::fs::copy(src, dir.join(fname)) {
            fail(&format!("cannot copy {}: {}", f, e));
        }
        modules.push(crate::project::module_name_of(src));
    }
    modules.sort();
    toml.set(&name, &version);
    toml.save();
    println!("added {} {} (import {})", name, version, modules.join(", "));
}

pub fn cmd_add(args: &[String]) {
    if args.is_empty() {
        fail("`add` needs a package, e.g. `pyfun add pyfun-textwrap`");
    }
    let path = match find_toml() {
        Some(p) => p,
        None => {
            let cwd = std::env::current_dir().unwrap_or_default();
            let name = cwd.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
            let p = cwd.join("pyfun.toml");
            if let Err(e) = std::fs::write(&p, format!("[project]\nname = \"{}\"\n\n[dependencies]\n", name)) {
                fail(&format!("cannot write {}: {}", p.display(), e));
            }
            println!("created pyfun.toml");
            p
        }
    };
    let mut toml = Toml::load(&path);
    for spec in args {
        add_one(spec, &mut toml);
    }
}

pub fn cmd_install(_args: &[String]) {
    let Some(path) = find_toml() else { fail("no pyfun.toml here or in any parent directory (`pyfun add <package>` creates one)") };
    let mut toml = Toml::load(&path);
    let deps = toml.deps();
    if deps.is_empty() {
        println!("no dependencies in pyfun.toml");
        return;
    }
    for (_, name, version) in deps {
        let spec = if version.is_empty() { name.clone() } else { format!("{}=={}", name, version) };
        add_one(&spec, &mut toml);
    }
}

pub fn cmd_remove(args: &[String]) {
    if args.is_empty() {
        fail("`remove` needs a package name");
    }
    let Some(path) = find_toml() else { fail("no pyfun.toml here or in any parent directory (`pyfun add <package>` creates one)") };
    let mut toml = Toml::load(&path);
    let root = path.parent().map(|p| p.to_path_buf()).unwrap_or_default();
    for name in args {
        if !toml.remove(name) {
            fail(&format!("`{}` is not a dependency in pyfun.toml", name));
        }
        let python = package_python();
        let _ = if have_uv() {
            Command::new("uv").args(["pip", "uninstall", "--python", &python, name]).status()
        } else {
            Command::new(&python).args(["-m", "pip", "uninstall", "-y", name]).status()
        };
        let dir = root.join(".pyfun").join("facades").join(normalized(name));
        let _ = std::fs::remove_dir_all(&dir);
        println!("removed {}", name);
    }
    toml.save();
}

// Loading, checking and lowering a single file or a multi-module project.

use crate::ast::*;
use crate::diag::{render, Diag};
use crate::infer::*;
use crate::lower::Lowerer;
use crate::types::*;
use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};

pub struct ModSrc {
    /// Pyfun module name (`Geometry`)
    pub name: String,
    /// file name (`geometry.pyfun`)
    pub file: String,
    pub path: PathBuf,
    pub src: String,
    pub prog: Program,
    pub imports: Vec<String>,
}

pub fn module_name_of(path: &Path) -> String {
    let stem = path.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
    let mut c = stem.chars();
    match c.next() {
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
        None => stem,
    }
}

pub fn py_module_of(file: &str) -> String {
    file.trim_end_matches(".pyfun").to_string()
}

fn imports_of(p: &Program) -> Vec<String> {
    p.decls
        .iter()
        .filter_map(|d| if let Decl::Import(n, _) = d { Some(n.clone()) } else { None })
        .collect()
}

pub enum LoadError {
    /// a plain message line (already prefixed with `error: `)
    Msg(String),
    /// a parse error inside a module
    Parse { module: Option<(String, String)>, src: String, diag: Diag },
}

pub fn read_source(path: &Path) -> Result<String, String> {
    match std::fs::read_to_string(path) {
        Ok(s) => Ok(s),
        Err(e) => Err(format!("error: cannot read {}: {}", path.display(), e)),
    }
}

/// Load the main file and every module it imports, dependencies first.
pub fn load(main: &Path, main_src: String) -> Result<Vec<ModSrc>, LoadError> {
    let prog = match crate::parser::parse_program(&main_src) {
        Ok(p) => p,
        Err(d) => return Err(LoadError::Parse { module: None, src: main_src, diag: d }),
    };
    let imports = imports_of(&prog);
    let main_name = module_name_of(main);
    let file = main.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
    let root = ModSrc { name: main_name.clone(), file, path: main.to_path_buf(), src: main_src, prog, imports };
    if root.imports.is_empty() {
        return Ok(vec![root]);
    }
    let dir = main.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from("."));
    let mut out: Vec<ModSrc> = Vec::new();
    let mut done: HashSet<String> = HashSet::new();
    let mut stack: Vec<String> = vec![main_name.clone()];
    let facades = crate::pkg::facade_dirs(main);
    visit(root, &dir, &facades, &mut out, &mut done, &mut stack)?;
    Ok(out)
}

fn visit(m: ModSrc, dir: &Path, facades: &[PathBuf], out: &mut Vec<ModSrc>, done: &mut HashSet<String>, stack: &mut Vec<String>) -> Result<(), LoadError> {
    for imp in m.imports.clone() {
        if done.contains(&imp) {
            continue;
        }
        if let Some(pos) = stack.iter().position(|s| *s == imp) {
            let mut cyc: Vec<String> = stack[pos..].to_vec();
            cyc.push(imp.clone());
            return Err(LoadError::Msg(format!("error: import cycle: {}", cyc.join(" -> "))));
        }
        let file = format!("{}.pyfun", imp.to_lowercase());
        // next to the program first, then in the vendored façades
        let mut path = dir.join(&file);
        let mut facade = false;
        if !path.exists() {
            if let Some(f) = facades.iter().map(|d| d.join(&file)).find(|p| p.exists()) {
                path = f;
                facade = true;
            }
        }
        // (a file that is not UTF-8 text is as good as missing)
        let src = match std::fs::read_to_string(&path) {
            Ok(s) => s,
            Err(_) => {
                return Err(LoadError::Msg(format!("error: cannot find module `{}` (expected `{}`), imported by `{}`", imp, file, m.name)));
            }
        };
        let prog = match crate::parser::parse_program(&src) {
            Ok(p) => p,
            Err(d) if facade => {
                return Err(LoadError::Msg(format!("error: in module `{}`: parse error: {} (at {}..{})", imp, d.msg, d.span.lo, d.span.hi)));
            }
            Err(d) => return Err(LoadError::Parse { module: Some((imp.clone(), file.clone())), src, diag: d }),
        };
        let imports = imports_of(&prog);
        let child = ModSrc { name: imp.clone(), file, path, src, prog, imports };
        stack.push(imp.clone());
        visit(child, dir, facades, out, done, stack)?;
        stack.pop();
    }
    done.insert(m.name.clone());
    out.push(m);
    Ok(())
}

/// What one module offers its importers.
#[derive(Clone, Default)]
pub struct Exports {
    pub values: HashMap<String, Scheme>,
    pub types: HashMap<String, TypeInfo>,
    pub ctors: HashMap<String, CtorInfo>,
    pub fields: HashMap<String, Vec<String>>,
    pub measures: HashMap<String, Option<Unit>>,
    /// arity of each exported function
    pub arities: HashMap<String, usize>,
}

pub struct Checked {
    pub mods: Vec<ModSrc>,
    pub checkers: Vec<Checker>,
    pub exports: HashMap<String, Exports>,
}

/// Check every module in order. On failure returns the rendered report.
/// A single file reports its errors (and holes); a project checks every
/// module and reports each one's errors under a header, with a total.
pub fn check_all(mods: Vec<ModSrc>, first_only: bool) -> Result<Checked, String> {
    let project = mods.len() > 1;
    let mut exports: HashMap<String, Exports> = HashMap::new();
    let mut checkers = Vec::new();
    let mut report = String::new();
    let mut total = 0;
    for m in &mods {
        let mut c = Checker::new();
        c.source = m.src.clone();
        for imp in &m.imports {
            if let Some(ex) = exports.get(imp) {
                install_exports(&mut c, imp, ex);
            }
        }
        c.check_program(&m.prog);
        if project {
            if !c.errors.is_empty() {
                report.push_str(&format!("-- module `{}` ({}) --\n", m.name, m.file));
                for d in &c.errors {
                    report.push_str(&render(&m.src, d));
                    report.push('\n');
                }
                total += c.errors.len();
            }
            exports.insert(m.name.clone(), collect_exports(&c, &m.prog));
            checkers.push(c);
            continue;
        }
        let hole_notes: Vec<Diag> = c.holes.iter().map(|h| Diag::note(crate::holes::hole_message(&c, h), h.span)).collect();
        if !hole_notes.is_empty() && c.errors.is_empty() && first_only {
            let h = &c.holes[0];
            let t = c.st.show(&h.ty);
            let name = match &h.name {
                Some(n) => format!("?{}", n),
                None => "?".to_string(),
            };
            let d = Diag::error(format!("cannot compile: unfilled hole `{}` has type `{}`{} (fill it in)", name, t, crate::holes::suggest_text(&c, h)), h.span);
            return Err(format!("{}\n", render(&m.src, &d)));
        }
        if !hole_notes.is_empty() && !first_only {
            let mut out = String::new();
            let all: Vec<&Diag> = c.errors.iter().chain(hole_notes.iter()).collect();
            let texts: Vec<String> = all.iter().map(|d| render(&m.src, d)).collect();
            out.push_str(&texts.join("\n\n"));
            out.push('\n');
            if !c.errors.is_empty() {
                let n = c.errors.len();
                out.push_str(&format!("\n{} error{}\n", n, if n == 1 { "" } else { "s" }));
            }
            let h = hole_notes.len();
            out.push_str(&format!("{} unfilled hole{}\n", h, if h == 1 { "" } else { "s" }));
            return Err(out);
        }
        if !c.errors.is_empty() {
            let mut out = String::new();
            if first_only {
                out.push_str(&render(&m.src, &c.errors[0]));
                out.push('\n');
            } else {
                for d in &c.errors {
                    out.push_str(&render(&m.src, d));
                    out.push_str("\n\n");
                }
                let n = c.errors.len();
                out.push_str(&format!("{} error{}\n", n, if n == 1 { "" } else { "s" }));
            }
            return Err(out);
        }
        exports.insert(m.name.clone(), collect_exports(&c, &m.prog));
        checkers.push(c);
    }
    if total > 0 {
        report.push_str(&format!("\n{} error{}\n", total, if total == 1 { "" } else { "s" }));
        return Err(report);
    }
    // a project is compiled whole: an unfilled hole anywhere stops it
    if project && first_only {
        for c in &checkers {
            if let Some(h) = c.holes.first() {
                let name = match &h.name {
                    Some(n) => format!("?{}", n),
                    None => "?".to_string(),
                };
                return Err(format!("error: lowering failed: cannot compile: unfilled hole `{}`\n", name));
            }
        }
    }
    Ok(Checked { mods, checkers, exports })
}

pub fn install_exports(c: &mut Checker, module: &str, ex: &Exports) {
    let mut me = ModuleExports::default();
    let mut names: Vec<&String> = ex.values.keys().collect();
    names.sort();
    for k in names {
        me.values.insert(k.clone(), ex.values[k].clone());
        me.order.push(k.clone());
    }
    c.modules.insert(module.to_string(), me);
    for (k, t) in &ex.types {
        let mut t = t.clone();
        if t.module.is_none() {
            t.module = Some(module.to_string());
        }
        c.types.entry(k.clone()).or_insert_with(|| t.clone());
        c.types.insert(format!("{}.{}", module, k), t);
    }
    for (k, ci) in &ex.ctors {
        let mut ci = ci.clone();
        if ci.module.is_none() {
            ci.module = Some(module.to_string());
        }
        c.ctors.insert(format!("{}.{}", module, k), ci);
    }
    for (k, v) in &ex.fields {
        let e = c.fields.entry(k.clone()).or_default();
        for x in v {
            if !e.contains(x) {
                e.push(x.clone());
            }
        }
    }
    for (k, v) in &ex.measures {
        c.measures.entry(k.clone()).or_insert_with(|| v.clone());
    }
}

pub fn collect_exports(c: &Checker, prog: &Program) -> Exports {
    let mut ex = Exports::default();
    // what is left unknown in an exported type (a binding that failed to
    // check, a `let mut`) is quantified, so importers get fresh variables
    let st = &c.st;
    for d in &prog.decls {
        match d {
            Decl::Let(l) => {
                let mut names = Vec::new();
                crate::check_decl::pat_names(&l.pat, &mut names);
                for n in names {
                    if let Some(g) = c.globals.get(&n) {
                        let ty = st.resolve(&g.scheme.ty);
                        ex.values.insert(n.clone(), Scheme { ty: quantify_all(&st, &ty), ord: g.scheme.ord.clone() });
                    }
                    if !l.params.is_empty() {
                        ex.arities.insert(n.clone(), l.params.len());
                    }
                }
            }
            Decl::Extern(e) => {
                if let Some(g) = c.globals.get(&e.name) {
                    ex.values.insert(e.name.clone(), g.scheme.clone());
                }
            }
            Decl::Type(t) => {
                if let Some(ti) = c.types.get(&t.name) {
                    ex.types.insert(t.name.clone(), ti.clone());
                }
                if let TypeBody::Sum(vs) = &t.body {
                    for v in vs {
                        if let Some(ci) = c.ctors.get(&v.name) {
                            ex.ctors.insert(v.name.clone(), ci.clone());
                        }
                    }
                }
                if let TypeBody::Opaque(_) = &t.body {
                    if let Some(ci) = c.ctors.get(&t.name) {
                        ex.ctors.insert(t.name.clone(), ci.clone());
                    }
                }
                if let TypeBody::Record(fs) = &t.body {
                    for (f, _, _) in fs {
                        ex.fields.entry(f.clone()).or_default().push(t.name.clone());
                    }
                }
            }
            Decl::ExternType(n, _, _, _) => {
                if let Some(ti) = c.types.get(n) {
                    ex.types.insert(n.clone(), ti.clone());
                }
            }
            Decl::Measure(n, _, _) => {
                if let Some(u) = c.measures.get(n) {
                    ex.measures.insert(n.clone(), u.clone());
                }
            }
            _ => {}
        }
    }
    ex
}

pub struct Emitted {
    /// (file name, contents)
    pub files: Vec<(String, String)>,
}

pub struct EmitOpts {
    pub py311: bool,
    pub native: bool,
}

/// Lower every module to Python source; a construct the lowering cannot
/// express ends the command (reported at the start of a single file).
pub fn emit_all(ck: &Checked, opts: &EmitOpts) -> Emitted {
    match try_emit_all(ck, opts) {
        Ok(em) => em,
        Err(msg) => {
            if ck.mods.len() > 1 {
                eprintln!("error: lowering failed: {}", msg);
            } else {
                let d = crate::diag::Diag::error(msg, crate::source::Span::new(0, 0));
                eprintln!("{}", crate::diag::render(&ck.mods[0].src, &d));
            }
            std::process::exit(1);
        }
    }
}

pub fn try_emit_all(ck: &Checked, opts: &EmitOpts) -> Result<Emitted, String> {
    let project = ck.mods.len() > 1;
    let mut files = Vec::new();
    let mut need_rt = false;
    for (i, m) in ck.mods.iter().enumerate() {
        let c = &ck.checkers[i];
        let mut l = Lowerer::new(c);
        l.py311 = opts.py311;
        l.native = opts.native;
        if project {
            l.project = true;
            l.all_ordered = true;
            // the names this module defines at top level
            let mut top: HashSet<String> = HashSet::new();
            for d in &m.prog.decls {
                match d {
                    Decl::Let(lt) => {
                        let mut names = Vec::new();
                        crate::check_decl::pat_names(&lt.pat, &mut names);
                        for n in names {
                            top.insert(crate::lower::mangle(&n));
                        }
                    }
                    Decl::Extern(e) => {
                        top.insert(crate::lower::mangle(&e.name));
                    }
                    _ => {}
                }
            }
            for imp in &m.imports {
                let file = format!("{}.pyfun", imp.to_lowercase());
                let pym = py_module_of(&file);
                let alias = if top.contains(&pym) { format!("_pf_{}", pym) } else { pym.clone() };
                l.project_modules.insert(imp.clone(), alias.clone());
                l.module_imports.push((pym, alias));
                if let Some(ex) = ck.exports.get(imp) {
                    for (k, a) in &ex.arities {
                        l.module_arities.insert(format!("{}.{}", imp, k), *a);
                    }
                }
            }
            for (k, ci) in c.ctors.iter() {
                if let Some((modname, _)) = k.split_once('.') {
                    let _ = (modname, ci);
                }
            }
        }
        l.collect_ordering();
        let code = l.lower_program(&m.prog.decls);
        if let Some(e) = l.error.take() {
            return Err(e);
        }
        let text = l.assemble(&m.prog.decls, &code);
        if l.uses_rt {
            need_rt = true;
        }
        files.push((format!("{}.py", py_module_of(&m.file)), text));
    }
    if project && need_rt {
        let rt = if opts.native { crate::lower5::runtime_module_native() } else { crate::lower5::runtime_module() };
        files.push(("_pyfun_rt.py".to_string(), rt));
    }
    Ok(Emitted { files })
}

/// Quantify every variable still free in `t`, after its existing ones.
fn quantify_all(st: &Store, t: &Ty) -> Ty {
    fn max_gen(t: &Ty, m: &mut [usize; 4]) {
        match t {
            Ty::Gen(i) => m[0] = m[0].max(i + 1),
            Ty::Con(_, args) => args.iter().for_each(|a| max_gen(a, m)),
            Ty::Tuple(ts) => ts.iter().for_each(|a| max_gen(a, m)),
            Ty::Fun(a, e, r) => {
                max_gen(a, m);
                if let Some(EffTail::Gen(i)) = e.tail {
                    m[3] = m[3].max(i + 1);
                }
                max_gen(r, m);
            }
            Ty::Num(k, u) => {
                if let Kind::Gen(i) = k {
                    m[1] = m[1].max(i + 1);
                }
                for a in u.0.keys() {
                    if let UAtom::Gen(i) = a {
                        m[2] = m[2].max(i + 1);
                    }
                }
            }
            Ty::Var(_) => {}
        }
    }
    #[derive(Default)]
    struct Q {
        next: [usize; 4],
        t: HashMap<usize, usize>,
        k: HashMap<usize, usize>,
        u: HashMap<usize, usize>,
        e: HashMap<usize, usize>,
    }
    fn fresh(map: &mut HashMap<usize, usize>, next: &mut usize, v: usize) -> usize {
        *map.entry(v).or_insert_with(|| {
            let i = *next;
            *next += 1;
            i
        })
    }
    fn go(st: &Store, t: &Ty, q: &mut Q) -> Ty {
        match st.shallow(t) {
            Ty::Var(v) => Ty::Gen(fresh(&mut q.t, &mut q.next[0], v)),
            Ty::Gen(i) => Ty::Gen(i),
            Ty::Con(n, args) => Ty::Con(n, args.iter().map(|a| go(st, a, q)).collect()),
            Ty::Tuple(ts) => Ty::Tuple(ts.iter().map(|a| go(st, a, q)).collect()),
            Ty::Fun(a, e, r) => {
                let a = go(st, &a, q);
                let mut e = st.eff(&e);
                if let Some(EffTail::Var(v)) = e.tail {
                    e.tail = Some(EffTail::Gen(fresh(&mut q.e, &mut q.next[3], v)));
                }
                let r = go(st, &r, q);
                Ty::Fun(Box::new(a), e, Box::new(r))
            }
            Ty::Num(k, u) => {
                let k = match st.kind(k) {
                    Kind::Var(v) => Kind::Gen(fresh(&mut q.k, &mut q.next[1], v)),
                    other => other,
                };
                let u = st.unit(&u);
                let mut out = std::collections::BTreeMap::new();
                for (a, e) in u.0 {
                    let a = match a {
                        UAtom::Var(v) => UAtom::Gen(fresh(&mut q.u, &mut q.next[2], v)),
                        other => other,
                    };
                    *out.entry(a).or_insert(0) += e;
                }
                Ty::Num(k, Unit(out))
            }
        }
    }
    let t = st.resolve(t);
    let mut q = Q::default();
    max_gen(&t, &mut q.next);
    go(st, &t, &mut q)
}

//! Phase 3 CLI: type-check, compile to Python, or echo the canonical form.
//!
//! Hand-rolled argument handling; the full clap subcommand surface (`fmt`,
//! `lsp`, …) arrives later — see `DESIGN.md` §10.
//!
//! Usage:
//!   pyfun check   <file.pyfun>                  # type-check, report diagnostics
//!   pyfun compile <file.pyfun> [-o <out>]       # type-check then lower to Python
//!   pyfun run     <file.pyfun> [--] [args...]   # compile then execute with Python
//!   pyfun parse   <file.pyfun>                  # canonical pretty-print
//!   pyfun <file.pyfun>                          # shorthand for `compile`
//!
//! `check`/`compile`/`run` operate over the **whole import graph** when the entry
//! file has `import`s (`DESIGN.md` §6.1): every module is checked/emitted, the
//! shared `_pyfun_rt.py` is produced, and `run` materializes the tree to a temp
//! directory. A file with **no imports behaves exactly as before** (single-file
//! path: `compile` to stdout/one file, `run` piped to the interpreter).

use std::path::Path;
use std::process::{Command, ExitCode, Stdio};

use pyfun::diagnostics::{self, Level};
use pyfun::project::{self, ProjectError};
use pyfun::python_emitter::PyTarget;
use pyfun::syntax::{Item, Module};

mod bundle;
mod kernel;
mod native_build;
mod packages;
mod repl;

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match args.first().map(String::as_str) {
        None | Some("-h") | Some("--help") => {
            help();
            ExitCode::SUCCESS
        }
        Some("-V") | Some("--version") | Some("version") => {
            println!("pyfun {}", env!("CARGO_PKG_VERSION"));
            ExitCode::SUCCESS
        }
        Some("check") => match args.get(1) {
            Some(path) => check(path),
            None => fail("`check` needs a file path"),
        },
        Some("compile") => match parse_compile_args(&args[1..]) {
            Ok((path, out, target, native)) => compile(path, out.as_deref(), target, native),
            Err(msg) => fail(&msg),
        },
        Some("run") => match args.get(1) {
            Some(path) => {
                // Everything after the path belongs to the program (even a
                // `-o` or `--help`), so it reaches `sys.argv` exactly as it
                // would when the compiled file is run with `python` directly.
                // One leading `--` is an optional separator and is consumed.
                let prog_args = match args.get(2).map(String::as_str) {
                    Some("--") => &args[3..],
                    _ => &args[2..],
                };
                run(path, prog_args)
            }
            None => fail("`run` needs a file path"),
        },
        Some("parse") => match args.get(1) {
            Some(path) => parse_only(path),
            None => fail("`parse` needs a file path"),
        },
        Some("bundle") => match bundle::parse_args(&args[1..]) {
            Ok(parsed) => bundle::run(parsed),
            Err(msg) => fail(&msg),
        },
        Some("build") => native_build::run(&args[1..]),
        Some("add") => packages::add(&args[1..]),
        Some("install") => packages::install(),
        Some("remove") => packages::remove(&args[1..]),
        Some("lsp") => lsp_server(),
        Some("repl") => repl::run(),
        Some("kernel-engine") => kernel::run(),
        // Shorthand: a bare path means `compile <path>` to stdout.
        Some(path) => compile(path, None, PyTarget::default(), false),
    }
}

