// Loading, checking and lowering a single file or a multi-module project.

use crate::ast::*;
use crate::diag::{render, Diag};
use crate::infer::*;
use crate::lower::Lowerer;
use crate::types::*;
use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};

pub struct ModSrc {
    /// Pyfun module name (`Geometry`)
    pub name: String,
    /// file name (`geometry.pyfun`)
    pub file: String,
    pub path: PathBuf,
    pub src: String,
    pub prog: Program,
    pub imports: Vec<String>,
}

pub fn module_name_of(path: &Path) -> String {
    let stem = path.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
    let mut c = stem.chars();
    match c.next() {
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
        None => stem,
    }
}

pub fn py_module_of(file: &str) -> String {
    file.trim_end_matches(".pyfun").to_string()
}

fn imports_of(p: &Program) -> Vec<String> {
    p.decls
        .iter()
        .filter_map(|d| if let Decl::Import(n, _) = d { Some(n.clone()) } else { None })
        .collect()
}

pub enum LoadError {
    /// a plain message line (already prefixed with `error: `)
    Msg(String),
    /// a parse error inside a module
    Parse { module: Option<(String, String)>, src: String, diag: Diag },
}

pub fn read_source(path: &Path) -> Result<String, String> {
    match std::fs::read_to_string(path) {
        Ok(s) => Ok(s),
        Err(e) => Err(format!("error: cannot read {}: {}", path.display(), e)),
    }
}

/// Load the main file and every module it imports, dependencies first.
pub fn load(main: &Path, main_src: String) -> Result<Vec<ModSrc>, LoadError> {
    let prog = match crate::parser::parse_program(&main_src) {
        Ok(p) => p,
        Err(d) => return Err(LoadError::Parse { module: None, src: main_src, diag: d }),
    };
    let imports = imports_of(&prog);
    let main_name = module_name_of(main);
    let file = main.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
    let root = ModSrc { name: main_name.clone(), file, path: main.to_path_buf(), src: main_src, prog, imports };
    if root.imports.is_empty() {
        return Ok(vec![root]);
    }
    let dir = main.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from("."));
    let mut out: Vec<ModSrc> = Vec::new();
    let mut done: HashSet<String> = HashSet::new();
    let mut stack: Vec<String> = vec![main_name.clone()];
    let facades = crate::pkg::facade_dirs(main);
    visit(root, &dir, &facades, &mut out, &mut done, &mut stack)?;
    Ok(out)
}

fn visit(m: ModSrc, dir: &Path, facades: &[PathBuf], out: &mut Vec<ModSrc>, done: &mut HashSet<String>, stack: &mut Vec<String>) -> Result<(), LoadError> {
    for imp in m.imports.clone() {
        if done.contains(&imp) {
            continue;
        }
        if let Some(pos) = stack.iter().position(|s| *s == imp) {
            let mut cyc: Vec<String> = stack[pos..].to_vec();
            cyc.push(imp.clone());
            return Err(LoadError::Msg(format!("error: import cycle: {}", cyc.join(" -> "))));
        }
        let file = format!("{}.pyfun", imp.to_lowercase());
        // next to the program first, then in the vendored façades
        let mut path = dir.join(&file);
        let mut facade = false;
        if !path.exists() {
            if let Some(f) = facades.iter().map(|d| d.join(&file)).find(|p| p.exists()) {
                path = f;
                facade = true;
            }
        }
        // (a file that is not UTF-8 text is as good as missing)
        let src = match std::fs::read_to_string(&path) {
            Ok(s) => s,
            Err(_) => {
                return Err(LoadError::Msg(format!("error: cannot find module `{}` (expected `{}`), imported by `{}`", imp, file, m.name)));
            }
        };
        let prog = match crate::parser::parse_program(&src) {
            Ok(p) => p,
            Err(d) if facade => {
                return Err(LoadError::Msg(format!("error: in module `{}`: parse error: {} (at {}..{})", imp, d.msg, d.span.lo, d.span.hi)));
            }
            Err(d) => return Err(LoadError::Parse { module: Some((imp.clone(), file.clone())), src, diag: d }),
        };
        let imports = imports_of(&prog);
        let child = ModSrc { name: imp.clone(), file, path, src, prog, imports };
        stack.push(imp.clone());
        visit(child, dir, facades, out, done, stack)?;
        stack.pop();
    }
    done.insert(m.name.clone());
    out.push(m);
    Ok(())
}

/// What one module offers its importers.
#[derive(Clone, Default)]
pub struct Exports {
    pub values: HashMap<String, Scheme>,
    pub types: HashMap<String, TypeInfo>,
    pub ctors: HashMap<String, CtorInfo>,
    pub fields: HashMap<String, Vec<String>>,
    pub measures: HashMap<String, Option<Unit>>,
    /// arity of each exported function
    pub arities: HashMap<String, usize>,
}

pub struct Checked {
    pub mods: Vec<ModSrc>,
    pub checkers: Vec<Checker>,
    pub exports: HashMap<String, Exports>,
}

/// Check every module in order. On failure returns the rendered report.
/// A single file reports its errors (and holes); a project checks every
/// module and reports each one's errors under a header, with a total.
pub fn check_all(mods: Vec<ModSrc>, first_only: bool) -> Result<Checked, String> {
    let project = mods.len() > 1;
    let mut exports: HashMap<String, Exports> = HashMap::new();
    let mut checkers = Vec::new();
    let mut report = String::new();
    let mut total = 0;
    for m in &mods {
        let mut c = Checker::new();
        c.source = m.src.clone();
        for imp in &m.imports {
            if let Some(ex) = exports.get(imp) {
                install_exports(&mut c, imp, ex);
            }
        }
        c.check_program(&m.prog);
        if project {
            if !c.errors.is_empty() {
                report.push_str(&format!("-- module `{}` ({}) --\n", m.name, m.file));
                for d in &c.errors {
                    report.push_str(&render(&m.src, d));
                    report.push('\n');
                }
                total += c.errors.len();
            }
            exports.insert(m.name.clone(), collect_exports(&c, &m.prog));
            checkers.push(c);
            continue;
        }
        let hole_notes: Vec<Diag> = c.holes.iter().map(|h| Diag::note(crate::holes::hole_message(&c, h), h.span)).collect();
        if !hole_notes.is_empty() && c.errors.is_empty() && first_only {
            let h = &c.holes[0];
            let t = c.st.show(&h.ty);
            let name = match &h.name {
                Some(n) => format!("?{}", n),
                None => "?".to_string(),
            };
            let d = Diag::error(format!("cannot compile: unfilled hole `{}` has type `{}`{} (fill it in)", name, t, crate::holes::suggest_text(&c, h)), h.span);
            return Err(format!("{}\n", render(&m.src, &d)));
        }
        if !hole_notes.is_empty() && !first_only {
            let mut out = String::new();
            let all: Vec<&Diag> = c.errors.iter().chain(hole_notes.iter()).collect();
            let texts: Vec<String> = all.iter().map(|d| render(&m.src, d)).collect();
            out.push_str(&texts.join("\n\n"));
            out.push('\n');
            if !c.errors.is_empty() {
                let n = c.errors.len();
                out.push_str(&format!("\n{} error{}\n", n, if n == 1 { "" } else { "s" }));
            }
            let h = hole_notes.len();
            out.push_str(&format!("{} unfilled hole{}\n", h, if h == 1 { "" } else { "s" }));
            return Err(out);
        }
        if !c.errors.is_empty() {
            let mut out = String::new();
            if first_only {
                out.push_str(&render(&m.src, &c.errors[0]));
                out.push('\n');
            } else {
                for d in &c.errors {
                    out.push_str(&render(&m.src, d));
                    out.push_str("\n\n");
                }
                let n = c.errors.len();
                out.push_str(&format!("{} error{}\n", n, if n == 1 { "" } else { "s" }));
            }
            return Err(out);
        }
        exports.insert(m.name.clone(), collect_exports(&c, &m.prog));
        checkers.push(c);
    }
    if total > 0 {
        report.push_str(&format!("\n{} error{}\n", total, if total == 1 { "" } else { "s" }));
        return Err(report);
    }
    // a project is compiled whole: an unfilled hole anywhere stops it
    if project && first_only {
        for c in &checkers {
            if let Some(h) = c.holes.first() {
                let name = match &h.name {
                    Some(n) => format!("?{}", n),
                    None => "?".to_string(),
                };
                return Err(format!("error: lowering failed: cannot compile: unfilled hole `{}`\n", name));
            }
        }
    }
    Ok(Checked { mods, checkers, exports })
}

pub fn install_exports(c: &mut Checker, module: &str, ex: &Exports) {
    let mut me = ModuleExports::default();
    let mut names: Vec<&String> = ex.values.keys().collect();
    names.sort();
    for k in names {
        me.values.insert(k.clone(), ex.values[k].clone());
        me.order.push(k.clone());
    }
    c.modules.insert(module.to_string(), me);
    for (k, t) in &ex.types {
        let mut t = t.clone();
        if t.module.is_none() {
            t.module = Some(module.to_string());
        }
        c.types.entry(k.clone()).or_insert_with(|| t.clone());
        c.types.insert(format!("{}.{}", module, k), t);
    }
    for (k, ci) in &ex.ctors {
        let mut ci = ci.clone();
        if ci.module.is_none() {
            ci.module = Some(module.to_string());
        }
        c.ctors.insert(format!("{}.{}", module, k), ci);
    }
    for (k, v) in &ex.fields {
        let e = c.fields.entry(k.clone()).or_default();
        for x in v {
            if !e.contains(x) {
                e.push(x.clone());
            }
        }
    }
    for (k, v) in &ex.measures {
        c.measures.entry(k.clone()).or_insert_with(|| v.clone());
    }
}

pub fn collect_exports(c: &Checker, prog: &Program) -> Exports {
    let mut ex = Exports::default();
    // what is left unknown in an exported type (a binding that failed to
    // check, a `let mut`) is quantified, so importers get fresh variables
    let st = &c.st;
    for d in &prog.decls {
        match d {
            Decl::Let(l) => {
                let mut names = Vec::new();
                crate::check_decl::pat_names(&l.pat, &mut names);
                for n in names {
                    if let Some(g) = c.globals.get(&n) {
                        let ty = st.resolve(&g.scheme.ty);
                        ex.values.insert(n.clone(), Scheme { ty: quantify_all(&st, &ty), ord: g.scheme.ord.clone() });
                    }
                    if !l.params.is_empty() {
                        ex.arities.insert(n.clone(), l.params.len());
                    }
                }
            }
            Decl::Extern(e) => {
                if let Some(g) = c.globals.get(&e.name) {
                    ex.values.insert(e.name.clone(), g.scheme.clone());
                }
            }
            Decl::Type(t) => {
                if let Some(ti) = c.types.get(&t.name) {
                    ex.types.insert(t.name.clone(), ti.clone());
                }
                if let TypeBody::Sum(vs) = &t.body {
                    for v in vs {
                        if let Some(ci) = c.ctors.get(&v.name) {
                            ex.ctors.insert(v.name.clone(), ci.clone());
                        }
                    }
                }
                if let TypeBody::Opaque(_) = &t.body {
                    if let Some(ci) = c.ctors.get(&t.name) {
                        ex.ctors.insert(t.name.clone(), ci.clone());
                    }
                }
                if let TypeBody::Record(fs) = &t.body {
                    for (f, _, _) in fs {
                        ex.fields.entry(f.clone()).or_default().push(t.name.clone());
                    }
                }
            }
            Decl::ExternType(n, _, _, _) => {
                if let Some(ti) = c.types.get(n) {
                    ex.types.insert(n.clone(), ti.clone());
                }
            }
            Decl::Measure(n, _, _) => {
                if let Some(u) = c.measures.get(n) {
                    ex.measures.insert(n.clone(), u.clone());
                }
            }
            _ => {}
        }
    }
    ex
}

pub struct Emitted {
    /// (file name, contents)
    pub files: Vec<(String, String)>,
}

pub struct EmitOpts {
    pub py311: bool,
    pub native: bool,
}

/// Lower every module to Python source; a construct the lowering cannot
/// express ends the command (reported at the start of a single file).
pub fn emit_all(ck: &Checked, opts: &EmitOpts) -> Emitted {
    match try_emit_all(ck, opts) {
        Ok(em) => em,
        Err(msg) => {
            if ck.mods.len() > 1 {
                eprintln!("error: lowering failed: {}", msg);
            } else {
                let d = crate::diag::Diag::error(msg, crate::source::Span::new(0, 0));
                eprintln!("{}", crate::diag::render(&ck.mods[0].src, &d));
            }
            std::process::exit(1);
        }
    }
}

pub fn try_emit_all(ck: &Checked, opts: &EmitOpts) -> Result<Emitted, String> {
    let project = ck.mods.len() > 1;
    let mut files = Vec::new();
    let mut need_rt = false;
    for (i, m) in ck.mods.iter().enumerate() {
        let c = &ck.checkers[i];
        let mut l = Lowerer::new(c);
        l.py311 = opts.py311;
        l.native = opts.native;
        if project {
            l.project = true;
            l.all_ordered = true;
            // the names this module defines at top level
            let mut top: HashSet<String> = HashSet::new();
            for d in &m.prog.decls {
                match d {
                    Decl::Let(lt) => {
                        let mut names = Vec::new();
                        crate::check_decl::pat_names(&lt.pat, &mut names);
                        for n in names {
                            top.insert(crate::lower::mangle(&n));
                        }
                    }
                    Decl::Extern(e) => {
                        top.insert(crate::lower::mangle(&e.name));
                    }
                    _ => {}
                }
            }
            for imp in &m.imports {
                let file = format!("{}.pyfun", imp.to_lowercase());
                let pym = py_module_of(&file);
                let alias = if top.contains(&pym) { format!("_pf_{}", pym) } else { pym.clone() };
                l.project_modules.insert(imp.clone(), alias.clone());
                l.module_imports.push((pym, alias));
                if let Some(ex) = ck.exports.get(imp) {
                    for (k, a) in &ex.arities {
                        l.module_arities.insert(format!("{}.{}", imp, k), *a);
                    }
                }
            }
            for (k, ci) in c.ctors.iter() {
                if let Some((modname, _)) = k.split_once('.') {
                    let _ = (modname, ci);
                }
            }
        }
        l.collect_ordering();
        let code = l.lower_program(&m.prog.decls);
        if let Some(e) = l.error.take() {
            return Err(e);
        }
        let text = l.assemble(&m.prog.decls, &code);
        if l.uses_rt {
            need_rt = true;
        }
        files.push((format!("{}.py", py_module_of(&m.file)), text));
    }
    if project && need_rt {
        let rt = if opts.native { crate::lower5::runtime_module_native() } else { crate::lower5::runtime_module() };
        files.push(("_pyfun_rt.py".to_string(), rt));
    }
    Ok(Emitted { files })
}

/// Quantify every variable still free in `t`, after its existing ones.
fn quantify_all(st: &Store, t: &Ty) -> Ty {
    fn max_gen(t: &Ty, m: &mut [usize; 4]) {
        match t {
            Ty::Gen(i) => m[0] = m[0].max(i + 1),
            Ty::Con(_, args) => args.iter().for_each(|a| max_gen(a, m)),
            Ty::Tuple(ts) => ts.iter().for_each(|a| max_gen(a, m)),
            Ty::Fun(a, e, r) => {
                max_gen(a, m);
                if let Some(EffTail::Gen(i)) = e.tail {
                    m[3] = m[3].max(i + 1);
                }
                max_gen(r, m);
            }
            Ty::Num(k, u) => {
                if let Kind::Gen(i) = k {
                    m[1] = m[1].max(i + 1);
                }
                for a in u.0.keys() {
                    if let UAtom::Gen(i) = a {
                        m[2] = m[2].max(i + 1);
                    }
                }
            }
            Ty::Var(_) => {}
        }
    }
    #[derive(Default)]
    struct Q {
        next: [usize; 4],
        t: HashMap<usize, usize>,
        k: HashMap<usize, usize>,
        u: HashMap<usize, usize>,
        e: HashMap<usize, usize>,
    }
    fn fresh(map: &mut HashMap<usize, usize>, next: &mut usize, v: usize) -> usize {
        *map.entry(v).or_insert_with(|| {
            let i = *next;
            *next += 1;
            i
        })
    }
    fn go(st: &Store, t: &Ty, q: &mut Q) -> Ty {
        match st.shallow(t) {
            Ty::Var(v) => Ty::Gen(fresh(&mut q.t, &mut q.next[0], v)),
            Ty::Gen(i) => Ty::Gen(i),
            Ty::Con(n, args) => Ty::Con(n, args.iter().map(|a| go(st, a, q)).collect()),
            Ty::Tuple(ts) => Ty::Tuple(ts.iter().map(|a| go(st, a, q)).collect()),
            Ty::Fun(a, e, r) => {
                let a = go(st, &a, q);
                let mut e = st.eff(&e);
                if let Some(EffTail::Var(v)) = e.tail {
                    e.tail = Some(EffTail::Gen(fresh(&mut q.e, &mut q.next[3], v)));
                }
                let r = go(st, &r, q);
                Ty::Fun(Box::new(a), e, Box::new(r))
            }
            Ty::Num(k, u) => {
                let k = match st.kind(k) {
                    Kind::Var(v) => Kind::Gen(fresh(&mut q.k, &mut q.next[1], v)),
                    other => other,
                };
                let u = st.unit(&u);
                let mut out = std::collections::BTreeMap::new();
                for (a, e) in u.0 {
                    let a = match a {
                        UAtom::Var(v) => UAtom::Gen(fresh(&mut q.u, &mut q.next[2], v)),
                        other => other,
                    };
                    *out.entry(a).or_insert(0) += e;
                }
                Ty::Num(k, Unit(out))
            }
        }
    }
    let t = st.resolve(t);
    let mut q = Q::default();
    max_gen(&t, &mut q.next);
    go(st, &t, &mut q)
}

// Lexer: bytes -> tokens with positions. Layout is decided by the parser from
// each token's column and whether it starts a line.

use crate::diag::Diag;
use crate::source::Span;

#[derive(Clone, Debug, PartialEq)]
pub enum Tok {
    Int(i64),
    Float(f64),
    Str(String),
    FStr(Vec<FPiece>),
    Ident(String),
    Upper(String),
    Hole(Option<String>),
    // keywords
    Let,
    Mut,
    Pure,
    Type,
    Measure,
    Extern,
    Import,
    Module,
    If,
    Then,
    Elif,
    Else,
    Match,
    Case,
    Fun,
    And,
    Or,
    Not,
    True,
    False,
    Return,
    With,
    As,
    Yield,
    Do,
    Try,
    // punctuation
    LParen,
    RParen,
    LBracket,
    RBracket,
    LBrace,
    RBrace,
    Comma,
    Dot,
    Ellipsis,
    Colon,
    Eq,
    Arrow,
    LArrow,
    Bar,
    Underscore,
    Bang,
    Caret,
    // operators
    Plus,
    Minus,
    Star,
    Slash,
    SlashSlash,
    Percent,
    StarStar,
    EqEq,
    NotEq,
    Lt,
    Le,
    Gt,
    Ge,
    PipeRight,
    PipeLeft,
    ComposeRight,
    ComposeLeft,
    /// (recovering) where a token failed to lex: it takes its place in the
    /// layout, and an expression simply skips it
    LexError,
    Eof,
}

#[derive(Clone, Debug, PartialEq)]
pub enum FPiece {
    Text(String),
    /// A `{...}` hole: its tokens (ending in Eof), the span of the content, and
    /// for `{expr=}` the source text echoed before the value.
    Hole { toks: Vec<Token>, span: Span, debug: Option<String> },
}

#[derive(Clone, Debug, PartialEq)]
pub struct Token {
    pub tok: Tok,
    pub span: Span,
    pub line: usize,
    pub col: usize,
    /// first token on its line
    pub bol: bool,
    /// whitespace (or a comment) right before this token
    pub space_before: bool,
}

pub fn describe(t: &Tok) -> String {
    match t {
        Tok::Int(n) => format!("integer `{}`", n),
        Tok::Float(f) => format!("float `{}`", f),
        Tok::Str(_) => "string literal".to_string(),
        Tok::Ident(s) | Tok::Upper(s) => format!("identifier `{}`", s),
        Tok::Eof => "end of input".to_string(),
        other => format!("`{}`", tok_text(other)),
    }
}

pub fn tok_text(t: &Tok) -> &'static str {
    match t {
        Tok::Let => "let",
        Tok::Mut => "mut",
        Tok::Pure => "pure",
        Tok::Type => "type",
        Tok::Measure => "measure",
        Tok::Extern => "extern",
        Tok::Import => "import",
        Tok::Module => "module",
        Tok::If => "if",
        Tok::Then => "then",
        Tok::Else => "else",
        Tok::Match => "match",
        Tok::Fun => "fun",
        Tok::And => "and",
        Tok::Or => "or",
        Tok::Not => "not",
        Tok::True => "true",
        Tok::False => "false",
        Tok::Return => "return",
        Tok::With => "with",
        Tok::Yield => "yield",
        Tok::Do => "do",
        Tok::LParen => "(",
        Tok::RParen => ")",
        Tok::LBracket => "[",
        Tok::RBracket => "]",
        Tok::LBrace => "{",
        Tok::RBrace => "}",
        Tok::Comma => ",",
        Tok::Dot => ".",
        Tok::Ellipsis => "...",
        Tok::Colon => ":",
        Tok::Eq => "=",
        Tok::Arrow => "->",
        Tok::LArrow => "<-",
        Tok::Bar => "|",
        Tok::Underscore => "_",
        Tok::Bang => "!",
        Tok::Caret => "^",
        Tok::Plus => "+",
        Tok::Minus => "-",
        Tok::Star => "*",
        Tok::Slash => "/",
        Tok::SlashSlash => "//",
        Tok::EqEq => "==",
        Tok::NotEq => "!=",
        Tok::Lt => "<",
        Tok::Le => "<=",
        Tok::Gt => ">",
        Tok::Ge => ">=",
        Tok::PipeRight => "|>",
        Tok::PipeLeft => "<|",
        Tok::ComposeRight => ">>",
        Tok::ComposeLeft => "<<",
        // the original's token display falls back to this for newer tokens
        _ => "token",
    }
}

fn keyword(s: &str) -> Option<Tok> {
    Some(match s {
        "let" => Tok::Let,
        "mut" => Tok::Mut,
        "pure" => Tok::Pure,
        "type" => Tok::Type,
        "measure" => Tok::Measure,
        "extern" => Tok::Extern,
        "import" => Tok::Import,
        "module" => Tok::Module,
        "if" => Tok::If,
        "then" => Tok::Then,
        "elif" => Tok::Elif,
        "else" => Tok::Else,
        "match" => Tok::Match,
        "case" => Tok::Case,
        "fun" => Tok::Fun,
        "and" => Tok::And,
        "or" => Tok::Or,
        "not" => Tok::Not,
        "true" => Tok::True,
        "false" => Tok::False,
        "return" => Tok::Return,
        "with" => Tok::With,
        "as" => Tok::As,
        "yield" => Tok::Yield,
        "do" => Tok::Do,
        "try" => Tok::Try,
        _ => return None,
    })
}

pub struct Lexed {
    pub toks: Vec<Token>,
    /// `##` doc lines: (line number, text)
    pub docs: Vec<(usize, String)>,
    pub error: Option<Diag>,
}

pub struct Lexer<'a> {
    src: &'a [u8],
    pos: usize,
    end: usize,
    line: usize,
    line_start: usize,
    toks: Vec<Token>,
    docs: Vec<(usize, String)>,
    last_line_with_token: usize,
    space: bool,
    tok_line: usize,
    tok_ls: usize,
    /// keep going after an error (the language server wants them all)
    recover: bool,
    errors: Vec<Diag>,
            ls = i + 1;
        }
    }
    (line, off - ls + 1)
}

impl<'a> Lexer<'a> {
    fn new(src: &'a [u8], pos: usize, end: usize, line: usize, line_start: usize) -> Self {
        Lexer {
            src,
            pos,
            end,
            line,
            line_start,
            toks: Vec::new(),
            docs: Vec::new(),
            last_line_with_token: 0,
            space: true,
            tok_line: line,
            tok_ls: line_start,
            recover: false,
            errors: Vec::new(),
        }
    }

    fn peek(&self, k: usize) -> u8 {
        let p = self.pos + k;
        if p < self.end {
            self.src[p]
        } else {
            0
        }
    }

    fn err(&self, msg: impl Into<String>, lo: usize, hi: usize) -> Diag {
        Diag::error(msg.into(), Span::new(lo, hi))
    }

    fn push(&mut self, tok: Tok, lo: usize) {
        let line = self.tok_line;
        let col = lo - self.tok_ls + 1;
        let bol = self.last_line_with_token != line;
        self.last_line_with_token = self.line;
        self.toks.push(Token { tok, span: Span::new(lo, self.pos), line, col, bol, space_before: self.space });
        self.space = false;
    }

    fn newline(&mut self) {
        // self.pos points just past a '\n'
        self.line += 1;
        self.line_start = self.pos;
    }

    fn run(&mut self) -> Result<(), Diag> {
        while self.pos < self.end {
            let start = self.pos;
            if let Err(e) = self.step() {
                if !self.recover {
                    return Err(e);
                }
                // resume after the bad text: past an unexpected character,
                // at a stray `}` (which then lexes as itself), else at the
                // end of the error's span
                let resume = if e.msg.starts_with("unexpected character") {
                    let c = self.src[start];
                    start + if c < 0x80 { 1 } else if c >= 0xF0 { 4 } else if c >= 0xE0 { 3 } else if c >= 0xC0 { 2 } else { 1 }
                } else if e.msg.starts_with("single `}`") {
                    e.span.lo
                } else {
                    e.span.hi.max(start + 1)
                };
                self.errors.push(e);
                // a stand-in for a failed token that starts its line (it
                // shapes the layout); one further along simply goes
                let line = self.tok_line;
                let col = start - self.tok_ls + 1;
                let bol = self.last_line_with_token != line;
                self.last_line_with_token = line;
                if bol {
                    self.toks.push(Token { tok: Tok::LexError, span: Span::new(start, start), line, col, bol, space_before: self.space });
                }
                self.pos = resume.min(self.end);
                let (l, _) = line_col(self.src, self.pos);
                let mut ls = self.pos;
                while ls > 0 && self.src[ls - 1] != b'\n' {
                    ls -= 1;
                }
                self.line = l;
                self.line_start = ls;
                self.space = true;
            }
        }
        Ok(())
    }

    fn step(&mut self) -> Result<(), Diag> {
        {
            let c = self.src[self.pos];
            self.tok_line = self.line;
            self.tok_ls = self.line_start;
            match c {
                b' ' | b'\t' | b'\r' => {
                    self.pos += 1;
                    self.space = true;
                }
                b'\n' => {
                    self.pos += 1;
                    self.newline();
                    self.space = true;
                }
                b'#' => {
                    let start = self.pos;
                    while self.pos < self.end && self.src[self.pos] != b'\n' {
                        self.pos += 1;
                    }
                    if start == self.line_start && self.src.get(start + 1) == Some(&b'#') && start + 1 < self.end {
                        let text = String::from_utf8_lossy(&self.src[start + 2..self.pos]).to_string();
                        // (one space after `##` is the marker's; the rest is the text's)
                        let text = text.strip_prefix(' ').unwrap_or(&text).trim_end().to_string();
                        self.docs.push((self.line, text));
                    }
                    self.space = true;
                }
                b'0'..=b'9' => self.number()?,
                b'"' => self.string(self.pos, false, false)?,
                b'f' if self.peek(1) == b'"' => self.string(self.pos, false, true)?,
                b'r' if self.peek(1) == b'"' => self.string(self.pos, true, false)?,
                c if is_ident_start(c) => {
                    let start = self.pos;
                    while self.pos < self.end && is_ident_char(self.src[self.pos]) {
                        self.pos += 1;
                    }
                    let s = std::str::from_utf8(&self.src[start..self.pos]).unwrap().to_string();
                    let tok = if s == "_" {
                        Tok::Underscore
                    } else if let Some(k) = keyword(&s) {
                        k
                    } else if s.as_bytes()[0].is_ascii_uppercase() {
                        Tok::Upper(s)
                    } else {
                        Tok::Ident(s)
                    };
                    self.push(tok, start);
                }
                b'?' => {
                    let start = self.pos;
                    self.pos += 1;
                    if self.pos < self.end && is_ident_start(self.src[self.pos]) {
                        let ns = self.pos;
                        while self.pos < self.end && is_ident_char(self.src[self.pos]) {
                            self.pos += 1;
                        }
                        let s = std::str::from_utf8(&self.src[ns..self.pos]).unwrap().to_string();
                        self.push(Tok::Hole(Some(s)), start);
                    } else {
                        self.push(Tok::Hole(None), start);
                    }
                }
                _ => self.punct()?,
            }
        }
        Ok(())
    }

    fn punct(&mut self) -> Result<(), Diag> {
        let start = self.pos;
        let c = self.src[self.pos];
        let n1 = self.peek(1);
        let n2 = self.peek(2);
        let (tok, len) = match c {
            b'(' => (Tok::LParen, 1),
            b')' => (Tok::RParen, 1),
            b'[' => (Tok::LBracket, 1),
            b']' => (Tok::RBracket, 1),
            b'{' => (Tok::LBrace, 1),
            b'}' => (Tok::RBrace, 1),
            b',' => (Tok::Comma, 1),
            b'.' if n1 == b'.' && n2 == b'.' => (Tok::Ellipsis, 3),
            b'.' => (Tok::Dot, 1),
            b':' => (Tok::Colon, 1),
            b'=' if n1 == b'=' => (Tok::EqEq, 2),
            b'=' => (Tok::Eq, 1),
            b'-' if n1 == b'>' => (Tok::Arrow, 2),
            b'-' => (Tok::Minus, 1),
            b'<' if n1 == b'-' => (Tok::LArrow, 2),
            b'<' if n1 == b'|' => (Tok::PipeLeft, 2),
            b'<' if n1 == b'<' => (Tok::ComposeLeft, 2),
            b'<' if n1 == b'=' => (Tok::Le, 2),
            b'<' => (Tok::Lt, 1),
            b'>' if n1 == b'>' => (Tok::ComposeRight, 2),
            b'>' if n1 == b'=' => (Tok::Ge, 2),
            b'>' => (Tok::Gt, 1),
            b'|' if n1 == b'>' => (Tok::PipeRight, 2),
            b'|' => (Tok::Bar, 1),
            b'&' if n1 == b'&' => return Err(self.err("use `and` instead of `&&`", start, start + 2)),
            b'!' if n1 == b'=' => (Tok::NotEq, 2),
            b'!' => (Tok::Bang, 1),
            b'^' => (Tok::Caret, 1),
            b'+' => (Tok::Plus, 1),
            b'*' if n1 == b'*' => (Tok::StarStar, 2),
            b'*' => (Tok::Star, 1),
            b'/' if n1 == b'/' => (Tok::SlashSlash, 2),
            b'/' => (Tok::Slash, 1),
            b'%' => (Tok::Percent, 1),
            _ => {
                let ch = c as char;
                return Err(self.err(format!("unexpected character {:?}", ch), start, start));
            }
        };
        self.pos += len;
        self.push(tok, start);
        Ok(())
    }

    fn number(&mut self) -> Result<(), Diag> {
        let start = self.pos;
        let c1 = self.peek(1);
        if self.src[self.pos] == b'0' && matches!(c1, b'x' | b'X' | b'o' | b'O' | b'b' | b'B') {
            let radix = match c1 {
                b'x' | b'X' => 16,
                b'o' | b'O' => 8,
                _ => 2,
            };
            self.pos += 2;
            let mut digits = String::new();
            loop {
                let c = self.peek(0);
                if (c as char).is_digit(radix) {
                    digits.push(c as char);
                    self.pos += 1;
                } else if c == b'_' && (self.peek(1) as char).is_digit(radix) && !digits.is_empty() {
                    self.pos += 1;
                } else {
                    break;
                }
            }
            match i64::from_str_radix(&digits, radix) {
                Ok(v) if !digits.is_empty() => {
                    self.push(Tok::Int(v), start);
                    Ok(())
                }
                        text.push(self.src[self.pos]);
                        self.pos += 1;
                    }
                    continue;
                }
                self.escape(&mut text)?;
                continue;
            }
            if fstr && c == b'{' {
                if self.peek(1) == b'{' {
                    text.push(b'{');
                    self.pos += 2;
                    continue;
                }
                if !text.is_empty() {
                    pieces.push(FPiece::Text(String::from_utf8_lossy(&text).to_string()));
                    text.clear();
                }
                let hole = self.fhole(start)?;
                pieces.push(hole);
                continue;
            }
            if fstr && c == b'}' {
                if self.peek(1) == b'}' {
                    text.push(b'}');
                    self.pos += 2;
                    continue;
                }
                return Err(self.err("single `}` in f-string; write `}}` for a literal brace", self.pos, self.pos));
            }
            text.push(c);
            self.pos += 1;
        }
        let tok = if fstr {
            if !text.is_empty() {
                pieces.push(FPiece::Text(String::from_utf8_lossy(&text).to_string()));
            }
            Tok::FStr(pieces)
        } else {
            Tok::Str(String::from_utf8_lossy(&text).to_string())
        };
        self.push(tok, start);
        Ok(())
    }

    fn unterminated(&self, start: usize, triple: bool, in_f: bool) -> Diag {
        // the literal runs to the end of the input
        let e = self.end;
        let msg = if in_f {
            "unterminated string literal in f-string"
        } else if triple {
            "unterminated triple-quoted string literal"
        } else {
            "unterminated string literal"
        };
        self.err(msg, start, e)
    }

    fn escape(&mut self, text: &mut Vec<u8>) -> Result<(), Diag> {
        let bs = self.pos;
        let c = self.peek(1);
        match c {
            b'n' => text.push(b'\n'),
            b't' => text.push(b'\t'),
            b'r' => text.push(b'\r'),
            b'"' => text.push(b'"'),
            b'\\' => text.push(b'\\'),
            b'u' => {
                if self.peek(2) != b'{' {
                    return Err(self.err("expected `{` after `\\u` (write `\\u{1F600}`)", bs, bs + 2));
                }
                let mut p = bs + 3;
                let mut hex = String::new();
                while p < self.end && (self.src[p] as char).is_ascii_hexdigit() {
                    hex.push(self.src[p] as char);
                    p += 1;
                }
                if p >= self.end || self.src[p] != b'}' {
                    return Err(self.err("expected `}` to close `\\u{...}`", bs, p));
                }
                p += 1;
                if hex.is_empty() || hex.len() > 6 {
                    return Err(self.err("invalid `\\u{...}` escape", bs, p));
                }
                let v = u32::from_str_radix(&hex, 16).unwrap();
                match char::from_u32(v) {
                    Some(ch) => {
                        let mut buf = [0u8; 4];
                        text.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                    }
                    None => return Err(self.err("invalid Unicode code point in `\\u{...}`", bs, p)),
                }
                self.pos = p;
                return Ok(());
            }
            _ => return Err(self.err("invalid escape sequence", bs, bs + 1)),
        }
        self.pos += 2;
        Ok(())
    }

    /// At a `{` inside an f-string: find the hole's extent, lex its content.
    fn fhole(&mut self, fstart: usize) -> Result<FPiece, Diag> {
        let open = self.pos;
        self.pos += 1;
        let cstart = self.pos;
        let mut depth = 0usize;
        // scan to the matching close brace, skipping nested strings
        loop {
            if self.pos >= self.end {
                // ran out: the enclosing literal is unterminated
                return Err(self.err("unterminated f-string (missing `}`)", fstart, self.end));
            }
            let c = self.src[self.pos];
            match c {
                b'{' => {
                    depth += 1;
                    self.pos += 1;
                }
                b'}' => {
                    if depth == 0 {
                        break;
                    }
                    depth -= 1;
                    self.pos += 1;
                }
                b'"' => {
                    // nested string: must close before the hole does
                    let s = self.pos;
                    let triple = self.peek(1) == b'"' && self.peek(2) == b'"';
                    self.pos += if triple { 3 } else { 1 };
                    loop {
                        // (a string may run over lines here too)
                        if self.pos >= self.end {
                            return Err(self.unterminated(s, triple, true));
                        }
                        let d = self.src[self.pos];
                        if d == b'\\' {
                            self.pos += 2;
                            continue;
                        }
                        if d == b'"' {
                            if triple {
                                if self.peek(1) == b'"' && self.peek(2) == b'"' {
                                    self.pos += 3;
                                    break;
                                }
                            } else {
                                self.pos += 1;
                                break;
                            }
                        }
                        if d == b'\n' {
                            self.pos += 1;
                            self.newline();
                            continue;
                        }
                        self.pos += 1;
                    }
                }
                b'#' => {
                    while self.pos < self.end && self.src[self.pos] != b'}' && self.src[self.pos] != b'\n' {
