// The interactive REPL: a session plus a Python worker process.

use crate::session::{EvalErr, Mode, Session};
use std::io::{BufRead, Read, Write};
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};

pub const WORKER_SCRIPT: &str = "
import io, sys, traceback
ns = {}
inp = sys.stdin.buffer
out = sys.stdout.buffer
while True:
    header = inp.read(8)
    if len(header) < 8:
        break
    code = inp.read(int(header)).decode('utf-8')
    buf = io.StringIO()
    saved = sys.stdout, sys.stderr
    sys.stdout = sys.stderr = buf
    try:
        exec(code, ns)
    except BaseException:
        traceback.print_exc()
    finally:
        sys.stdout, sys.stderr = saved
    payload = buf.getvalue().encode('utf-8')
    out.write(b'%08d' % len(payload))
    out.write(payload)
    out.flush()
";

const HELP: &str = "Commands:
  :type <expr>   show an expression's inferred type (no evaluation)
  :{ … :}        enter a multi-line block (e.g. mutually-recursive defs)
  :reset         forget all definitions entered this session
  :help          show this help
  :quit          exit (or Ctrl-D)
Enter a `let`/`type`/`extern` definition to remember it, or an
expression to evaluate it.";

pub struct Worker {
    child: Child,
    stdin: ChildStdin,
    stdout: ChildStdout,
}

impl Worker {
    pub fn spawn(python: &str) -> Result<Worker, String> {
        let mut child = Command::new(python)
            .arg("-c")
            .arg(WORKER_SCRIPT)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .spawn()
            .map_err(|e| e.to_string())?;
        let stdin = child.stdin.take().unwrap();
        let stdout = child.stdout.take().unwrap();
        Ok(Worker { child, stdin, stdout })
    }

    pub fn request(&mut self, code: &str) -> Result<String, String> {
        let bytes = code.as_bytes();
        let mut msg = format!("{:08}", bytes.len()).into_bytes();
        msg.extend_from_slice(bytes);
        self.stdin.write_all(&msg).map_err(|e| e.to_string())?;
        self.stdin.flush().map_err(|e| e.to_string())?;
        let mut header = [0u8; 8];
        self.stdout.read_exact(&mut header).map_err(|e| e.to_string())?;
        let n: usize = std::str::from_utf8(&header)
            .ok()
            .and_then(|s| if s.bytes().all(|b| b.is_ascii_digit()) { s.parse().ok() } else { None })
            .ok_or_else(|| "bad response header".to_string())?;
        let mut payload = vec![0u8; n];
        self.stdout.read_exact(&mut payload).map_err(|e| e.to_string())?;
        Ok(String::from_utf8_lossy(&payload).into_owned())
    }

    pub fn kill(mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

pub struct Repl {
    session: Session,
    python: String,
    worker: Option<Worker>,
}

impl Repl {
    /// Run code in the worker, restarting it once on failure.
    fn run(&mut self, code: &str) {
        let out = std::io::stdout();
        if self.worker.is_none() {
            match Worker::spawn(&self.python) {
                Ok(w) => self.worker = Some(w),
                Err(e) => {
                    eprintln!("cannot start python worker: {}", e);
                    return;
                }
            }
            match self.worker.as_mut().unwrap().request(code) {
                Ok(o) => {
                    print!("{}", o);
                    let _ = out.lock().flush();
                }
                Err(e) => {
                    eprintln!("cannot start python worker: {}", e);
                    if let Some(w) = self.worker.take() {
                        w.kill();
                    }
                }
            }
            return;
        }
        match self.worker.as_mut().unwrap().request(code) {
            Ok(o) => {
                print!("{}", o);
                let _ = out.lock().flush();
                return;
            }
            Err(e) => eprintln!("python worker error: {}", e),
        }
        if let Some(w) = self.worker.take() {
            w.kill();
        }
        let mut w = match Worker::spawn(&self.python) {
            Ok(w) => w,
            Err(e) => {
                eprintln!("cannot restart python worker: {}", e);
                return;
            }
        };
        if let Some(rebuild) = self.session.rebuild_code() {
            eprintln!("(python worker restarted — definitions re-executed to rebuild state)");
            match w.request(&rebuild) {
                Ok(o) => {
                    print!("{}", o);
                    let _ = out.lock().flush();
                }
                Err(e) => {
                    eprintln!("cannot restart python worker: {}", e);
                    w.kill();
                    return;
                }
            }
        } else {
            self.session.sent.clear();
        }
        match w.request(code) {
            Ok(o) => {
                print!("{}", o);
                let _ = out.lock().flush();
                self.worker = Some(w);
            }
            Err(e) => {
                eprintln!("python worker failed again: {}", e);
                w.kill();
            }
        }
    }

    fn eval(&mut self, input: &str, block: bool) {
        match self.session.eval(input, block) {
            Ok(r) => {
                for e in &r.echoes {
                    println!("{}", e);
                }
                if !r.code.is_empty() {
                    self.run(&r.code);
                }
            }
            Err(EvalErr::Parse(s)) => eprintln!("{}", s),
            Err(EvalErr::Type(errs)) => {
                for e in errs {
                    eprintln!("{}", e);
                }
            }
            Err(EvalErr::Compile(echoes, errs)) => {
                for e in &echoes {
                    println!("{}", e);
                }
                for e in errs {
                    eprintln!("{}", e);
                }
            }
        }
    }
}

enum Line {
    Text(String),
    Eof,
    Invalid,
}

fn read_line(stdin: &mut std::io::StdinLock) -> Line {
    let mut buf = Vec::new();
    match stdin.read_until(b'\n', &mut buf) {
        Ok(0) => Line::Eof,
        Ok(_) => match String::from_utf8(buf) {
            Ok(s) => Line::Text(s.trim_end_matches('\n').trim_end_matches('\r').to_string()),
            Err(_) => Line::Invalid,
        },
        Err(_) => Line::Invalid,
    }
}

fn prompt(p: &str) {
    print!("{}", p);
    let _ = std::io::stdout().flush();
}

pub fn run_repl() -> ! {
    let python = match crate::find_python(false) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };
    println!("Pyfun REPL — :help for commands, :quit to exit.");
    let mut repl = Repl { session: Session::new(Mode::Repl), python, worker: None };
    let stdin = std::io::stdin();
    let mut lock = stdin.lock();
    loop {
        prompt("pyfun> ");
        let line = match read_line(&mut lock) {
            Line::Eof => {
                println!();
                break;
            }
            Line::Invalid => {
                eprintln!("input error: stream did not contain valid UTF-8");
                break;
            }
            Line::Text(t) => t,
        };
        let t = line.trim();
        if t.is_empty() {
            continue;
        }
        if t.starts_with(':') {
            let (word, rest) = match t.find(|c: char| c.is_whitespace()) {
                Some(i) => (&t[..i], t[i..].trim()),
                None => (t, ""),
            };
            match word {
                ":" => continue,
                ":quit" | ":q" | ":exit" => {
                    let _ = std::io::stdout().flush();
                    if let Some(w) = repl.worker.take() {
                        w.kill();
                    }
                    std::process::exit(0);
                }
                ":help" | ":h" | ":?" => println!("{}", HELP),
                ":reset" => {
                    repl.session.reset();
                    if let Some(w) = repl.worker.take() {
                        w.kill();
                    }
                    println!("(session reset)");
                }
                ":type" | ":t" => {
                    if rest.is_empty() {
                        println!("usage: :type <expression>");
                    } else {
                        match repl.session.type_of(rest) {
                            Ok(s) => println!("{}", s),
                            Err(errs) => {
                                for e in errs {
                                    if e.starts_with('(') {
                                        println!("{}", e);
                                    } else {
                                        eprintln!("{}", e);
                                    }
                                }
                            }
                        }
                    }
                }
                ":{" => {
                    let mut lines: Vec<String> = Vec::new();
                    let mut eof = false;
                    loop {
                        prompt("...... ");
                        match read_line(&mut lock) {
                            Line::Eof => {
                                eof = true;
                                break;
                            }
                            Line::Invalid => {
                                eprintln!("input error: stream did not contain valid UTF-8");
                                std::process::exit(0);
                            }
                            Line::Text(l) => {
                                if l.trim() == ":}" {
                                    break;
                                }
                                lines.push(l);
                            }
                        }
                    }
                    // (each of the block's lines keeps its line end)
                    let text: String = lines.iter().map(|l| format!("{}\n", l)).collect();
                    if !text.trim().is_empty() {
                        repl.eval(&text, true);
                    }
                    if eof {
                        // the block ended at end of input
                        prompt("pyfun> ");
                        println!();
                        break;
                    }
                }
                _ => println!("unknown command `{}` — :help for the list", word),
            }
            continue;
        }
        repl.eval(t, false);
    }
    if let Some(w) = repl.worker.take() {
        w.kill();
    }
    std::process::exit(0);
}

// The session engine behind the Jupyter kernel: length-framed requests on
// stdin, `status / info / code` frame triples on stdout.

use crate::ast::Decl;
use crate::session::{EvalErr, EvalOk, Mode, Session};
use std::io::{Read, Write};

fn read_frame(r: &mut impl Read) -> Option<Vec<u8>> {
    let mut header = [0u8; 8];
    r.read_exact(&mut header).ok()?;
    let s = std::str::from_utf8(&header).ok()?;
    if !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    let n: usize = s.parse().ok()?;
    let mut buf = vec![0u8; n];
    r.read_exact(&mut buf).ok()?;
    Some(buf)
}

fn frame(out: &mut Vec<u8>, s: &str) {
    out.extend_from_slice(format!("{:08}", s.len()).as_bytes());
    out.extend_from_slice(s.as_bytes());
}

fn error_reply(e: EvalErr) -> (String, String, String) {
    match e {
        EvalErr::Parse(s) => ("error".to_string(), s, String::new()),
        EvalErr::Type(errs) => {
            let mut s = String::new();
            for e in errs {
                s.push_str(&e);
                s.push('\n');
            }
            ("error".to_string(), s, String::new())
        }
        EvalErr::Compile(_, errs) => ("error".to_string(), errs.join("\n"), String::new()),
    }
}

fn echo_text(r: &EvalOk) -> String {
    let mut info = String::new();
    for e in &r.echoes {
        info.push_str(e);
        info.push('\n');
    }
    info
}

/// A cell's definitions are entered first (and stay, whatever follows);
/// a trailing expression is then evaluated on its own. The cell is cut
/// where the expression's own text starts (inside its parentheses, for a
/// parenthesized one), and the text before it, unless blank, is entered as
/// it stands.
fn eval_cell(session: &mut Session, cell: &str) -> (String, String, String) {
    let split = match crate::parser::parse_program(cell) {
        Ok(p) => match p.decls.last() {
            Some(Decl::Expr(e)) => Some(e.span.lo),
            Some(Decl::Assign(_, _, _, whole)) => Some(whole.lo),
            _ => None,
        },
        _ => None,
    };
    let Some(at) = split else {
        return match session.eval(cell, true) {
            Ok(r) => ("ok".to_string(), echo_text(&r), r.code),
            Err(e) => error_reply(e),
        };
    };
    let head = &cell[..at];
    let defs = if head.trim().is_empty() {
        None
    } else {
        match session.eval_part(head, true, true) {
            Ok(r) => Some(r),
            Err(e) => return error_reply(e),
        }
    };
    match session.eval(&cell[at..], true) {
        Ok(r) => {
            let Some(defs) = defs else {
                return ("ok".to_string(), echo_text(&r), r.code);
            };
            let mut info = echo_text(&defs);
            info.push_str(&echo_text(&r));
            let mut code = defs.code.clone();
            // an empty expression's `pass` only fills an otherwise empty reply
            if !(r.fallback_pass && (!defs.code.is_empty() || defs.all_dup)) {
                code.push_str(&r.code);
            }
            ("ok".to_string(), info, code)
        }
        Err(e) => error_reply(e),
    }
}

pub fn run_kernel() -> ! {
    let mut session = Session::new(Mode::Kernel);
    let stdin = std::io::stdin();
    let mut input = stdin.lock();
    let stdout = std::io::stdout();
    loop {
        let Some(op) = read_frame(&mut input) else { break };
        let Some(payload) = read_frame(&mut input) else { break };
        let op = String::from_utf8_lossy(&op).to_string();
        let payload = String::from_utf8_lossy(&payload).to_string();
        let (status, info, code) = match op.as_str() {
            "eval" => {
                let mut cell = payload.as_str();
                // a first line of `:reset` starts a fresh session
                let first = cell.lines().next().unwrap_or("");
                if first.trim() == ":reset" {
                    session.reset();
                    cell = match cell.find('\n') {
                        Some(i) => &cell[i + 1..],
                        None => "",
                    };
                }
                if cell.trim().is_empty() {
                    ("ok".to_string(), String::new(), String::new())
                } else {
                    eval_cell(&mut session, cell)
                }
            }
            "type" => match session.type_of(&payload) {
                Ok(s) => ("ok".to_string(), s, String::new()),
                Err(errs) => {
                    if errs.len() == 1 && errs[0].starts_with('(') {
                        ("error".to_string(), errs[0].clone(), String::new())
                    } else {
                        let mut s = String::new();
                        for e in errs {
                            s.push_str(&e);
                            s.push('\n');
                        }
                        ("error".to_string(), s, String::new())
                    }
                }
            },
            other => ("error".to_string(), format!("unknown op `{}`", other), String::new()),
        };
        let mut out = Vec::new();
        frame(&mut out, &status);
        frame(&mut out, &info);
        frame(&mut out, &code);
        let mut lock = stdout.lock();
        let _ = lock.write_all(&out);
        let _ = lock.flush();
    }
    std::process::exit(0);
}
// An incremental session shared by the REPL and the Jupyter kernel engine:
// every input is checked and compiled together with the definitions entered
// before it, and only the new code (plus infrastructure not yet sent) is
// handed to Python.

use crate::ast::*;
use crate::diag::{render, Diag};
use crate::infer::Checker;
use crate::lower::Lowerer;
use crate::py::*;
use crate::types::Ty;
use std::collections::HashSet;

#[derive(Clone, Copy, PartialEq)]
pub enum Mode {
    Repl,
    Kernel,
}

pub struct Session {
    pub mode: Mode,
    pub entries: Vec<String>,
    /// infrastructure chunks already sent to Python
    pub sent: HashSet<String>,
    /// a definition in the session has code (the module is not empty)
    pub code_sent: bool,
    /// the code chunks the session's entries ran
    pub known: HashSet<String>,
}

pub enum EvalErr {
    /// a parse error of the input on its own
    Parse(String),
    /// type errors in the session
    Type(Vec<String>),
    /// compile errors (unfilled holes); echoes were computed
    Compile(Vec<String>, Vec<String>),
}

pub struct EvalOk {
    pub echoes: Vec<String>,
    pub code: String,
    /// the input was stored as a session entry
    pub stored: bool,
    /// every definition repeated one already entered
    pub all_dup: bool,
    /// the code is the `pass` an expression with nothing to run stands for
    pub fallback_pass: bool,
}

pub fn session_source(entries: &[String], input: &str) -> String {
    let mut s = String::from("\n");
    for e in entries {
        s.push_str(e);
        s.push('\n');
    }
    s.push_str(input);
    s
}

fn is_unit(t: &Ty) -> bool {
    matches!(t, Ty::Con(n, _) if n == "unit")
}

/// Split infrastructure text into top-level chunks.
pub fn chunks(text: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut in_decorator = false;
    for line in text.split_inclusive('\n') {
        let top = !line.starts_with(' ') && !line.starts_with('\t');
        if top && !in_decorator && !cur.is_empty() {
            out.push(std::mem::take(&mut cur));
        }
        in_decorator = line.starts_with('@');
        cur.push_str(line);
    }
    if !cur.is_empty() {
        out.push(cur);
    }
    out
}

fn dedupable(chunk: &str) -> bool {
    chunk.starts_with("import ")
        || chunk.starts_with("from ")
        || chunk.starts_with('@')
        || chunk.starts_with("class ")
        || chunk.starts_with("def ")
        || chunk.starts_with("async def ")
}

impl Session {
    pub fn new(mode: Mode) -> Session {
        Session { mode, entries: Vec::new(), sent: HashSet::new(), code_sent: false, known: HashSet::new() }
    }

    pub fn reset(&mut self) {
        self.entries.clear();
        self.sent.clear();
        self.code_sent = false;
        self.known.clear();
    }

    /// Compile every definition of the session as one module (for rebuilding
    /// a restarted worker).
    pub fn rebuild_code(&mut self) -> Option<String> {
        if self.entries.is_empty() {
            return None;
        }
        let src = session_source(&self.entries, "");
        let prog = crate::parser::parse_program(&src).ok()?;
        let mut c = Checker::new();
        c.check_program(&prog);
        let mut l = Lowerer::new(&c);
        l.collect_ordering();
        let code = l.lower_program(&prog.decls);
        let text = l.assemble(&prog.decls, &code);
        self.sent.clear();
        for ch in chunks(&text) {
            if dedupable(&ch) {
                self.sent.insert(ch);
            }
        }
        Some(text)
    }

    pub fn eval(&mut self, input: &str, block: bool) -> Result<EvalOk, EvalErr> {
        self.eval_part(input, block, false)
    }

    /// `head`: every declaration of the input is entered (a kernel cell's
    /// part before its trailing expression), expressions as statements.
    pub fn eval_part(&mut self, input: &str, block: bool, head: bool) -> Result<EvalOk, EvalErr> {
        // (a kernel cell's head is only read after the session's text)
        let parsed = match crate::parser::parse_program(input) {
            Ok(p) => Some(p),
            Err(_) if head => None,
            Err(d) => return Err(EvalErr::Parse(render(input, &d))),
        };
        let src = session_source(&self.entries, input);
        // (an input that parses alone but not after the session's text is
        // reported like the session's other errors: every one the text has)
        let prog = match crate::parser::parse_program(&src) {
            Ok(p) => p,
            Err(d) => {
                let (_, mut all, parse_errors) = crate::parser::parse_program_recover(&src);
                all.extend(parse_errors);
                all.sort_by_key(|d| d.span.lo);
                if all.is_empty() {
                    all.push(d);
                }
                return Err(EvalErr::Type(all.iter().map(|d| render(&src, d)).collect()));
            }
        };
        let k = match &parsed {
            Some(p) => p.decls.len(),
            None => {
                let lo = src.len() - input.len();
                prog.decls.iter().filter(|d| decl_span(d).lo >= lo).count()
            }
        };
        let n = prog.decls.len();
        let first = n.saturating_sub(k);
        // the kind of input (as the input reads on its own)
        // (an assignment is an expression too)
        let last_expr = match parsed.as_ref().and_then(|p| p.decls.last()) {
            Some(Decl::Expr(e)) => Some(e.span.lo),
            Some(Decl::Assign(_, _, _, whole)) => Some(whole.lo),
            _ => None,
        };
        let trailing_expr = k > 0 && last_expr.is_some();
        let expr_only = k == 1 && trailing_expr;
        let _ = block;
        let (defs_end, trailing) = match self.mode {
            Mode::Repl => {
                if expr_only {
                    (first, true)
                } else {
                    (n, false)
                }
            }
            Mode::Kernel => {
                if trailing_expr && !head {
                    (n.saturating_sub(1).max(first), true)
                } else {
                    (n, false)
                }
            }
        };
        let mut c = Checker::new();
        c.source = src.clone();
        c.check_program(&prog);
        if !c.errors.is_empty() {
            let errs = c.errors.iter().map(|d| render(&src, d)).collect();
            return Err(EvalErr::Type(errs));
        }
        // echoes for the input's let bindings
        let mut echoes = Vec::new();
        for d in &prog.decls[first..defs_end] {
            if let Decl::Let(l) = d {
                if l.active.is_some() {
                    continue;
                }
                match &l.pat.kind {
                    PatKind::Var(name) => {
                        let t = c.binding_types.get(&crate::infer::key(l.name_span)).cloned();
                        let shown = match t {
                            Some(t) => {
                                let s = if l.mutable { crate::types::Scheme::mono(t) } else { generalize_display(&mut c, &t) };
                                c.st.show(&s.ty)
                            }
                            None => c.globals.get(name).map(|g| c.st.show(&g.scheme.ty)).unwrap_or_default(),
                        };
                        echoes.push(format!("{} : {}", name, shown));
                    }
                    _ => {
                        let mut names = Vec::new();
                        crate::check_decl::pat_names(&l.pat, &mut names);
                        for nm in names {
                            if let Some(g) = c.globals.get(&nm) {
                                echoes.push(format!("{} : {}", nm, c.st.show(&g.scheme.ty)));
                            }
                        }
                    }
                }
            }
        }
        // a value to print is compiled as `print (…)`: the session is read
        // again with the input's expression wrapped (the rest of the input
        // goes inside the parentheses), and what that reading finds is
        // reported against it
        let input_lo = src.len() - input.len();
        let unit_last = match prog.decls.last() {
            Some(Decl::Expr(e)) => c.expr_types.get(&crate::infer::key(e.span)).map_or(false, |t| is_unit(&c.st.resolve(t))),
            Some(Decl::Assign(..)) => true,
            _ => false,
        };
        let (src, prog, c) = match last_expr {
            Some(lo) if trailing && !unit_last => {
                let at = input_lo + lo;
                let wrapped = format!("{}print ({})", &src[..at], &src[at..]);
                let wprog = match crate::parser::parse_program(&wrapped) {
                    Ok(p) => p,
                    Err(d) => return Err(EvalErr::Compile(echoes, vec![render(&wrapped, &d)])),
                };
