use crate::ast::*;
use crate::diag::Diag;
use crate::lexer::{describe, FPiece, Tok, Token};
use crate::source::Span;

#[derive(Clone, Copy, Debug)]
enum Layout {
    /// statements of a block start at this column
    Block(usize),
    /// inside brackets: line breaks mean nothing
    NoLayout,
    /// one item of a computation expression body
    CeItem { item_col: usize, expr_col: usize, line: usize, kw: &'static str },
}

pub struct Parser {
    toks: Vec<Token>,
    pos: usize,
    layout: Vec<Layout>,
    docs: Vec<(usize, String)>,
    pub errors: Vec<Diag>,
}

type PResult<T> = Result<T, Diag>;

fn is_continuation(t: &Tok) -> bool {
    matches!(
        t,
        Tok::Plus
            | Tok::Minus
            | Tok::Star
            | Tok::Slash
            | Tok::SlashSlash
            | Tok::Percent
            | Tok::StarStar
            | Tok::EqEq
            | Tok::NotEq
            | Tok::Lt
            | Tok::Le
            | Tok::Gt
            | Tok::Ge
            | Tok::PipeRight
            | Tok::PipeLeft
            | Tok::ComposeRight
            | Tok::ComposeLeft
            | Tok::And
            | Tok::Or
            | Tok::Dot
            | Tok::Eq
            | Tok::Arrow
            | Tok::Colon
            | Tok::Bar
            | Tok::Then
            | Tok::Elif
            | Tok::Else
            | Tok::With
            | Tok::RParen
            | Tok::RBracket
            | Tok::RBrace
            | Tok::Comma
    )
}

fn starts_atom(t: &Tok) -> bool {
    matches!(
        t,
        Tok::Int(_)
            | Tok::Float(_)
            | Tok::Str(_)
            | Tok::FStr(_)
            | Tok::Ident(_)
            | Tok::Upper(_)
            | Tok::Hole(_)
            | Tok::True
            | Tok::False
            | Tok::LParen
            | Tok::LBracket
            | Tok::LBrace
    )
}

#[derive(PartialEq)]
enum Boundary {
    No,
    Statement,
    Block,
}

impl Parser {
    pub fn new(toks: Vec<Token>, docs: Vec<(usize, String)>) -> Parser {
        Parser { toks, pos: 0, layout: vec![Layout::Block(1)], docs, errors: Vec::new() }
    }

    // ---- token access -------------------------------------------------

    fn raw(&self) -> &Token {
        &self.toks[self.pos.min(self.toks.len() - 1)]
    }
    fn raw_at(&self, k: usize) -> &Token {
        &self.toks[(self.pos + k).min(self.toks.len() - 1)]
    }

    fn boundary_of(&self, t: &Token) -> Boundary {
        if t.tok == Tok::Eof {
            return Boundary::Statement;
        }
        if !t.bol {
            return Boundary::No;
        }
        match self.layout.last() {
            None | Some(Layout::NoLayout) => Boundary::No,
            Some(Layout::Block(col)) => {
                if t.col < *col {
                    Boundary::Block
                } else if t.col == *col && !is_continuation(&t.tok) {
                    Boundary::Statement
                } else {
                    Boundary::No
                }
            }
            Some(Layout::CeItem { item_col, expr_col, .. }) => {
                if t.col > *expr_col || (is_continuation(&t.tok) && t.col > *item_col) {
                    Boundary::No
                } else {
                    Boundary::Statement
                }
            }
        }
    }

    fn at_boundary(&self) -> bool {
        self.boundary_of(self.raw()) != Boundary::No
    }

    /// The next token if it is not cut off by layout.
    fn peek(&self) -> Option<&Tok> {
        let t = self.raw();
        if self.boundary_of(t) != Boundary::No {
            None
        } else {
            Some(&t.tok)
        }
    }

    fn check(&self, t: &Tok) -> bool {
        self.peek() == Some(t)
    }

    fn bump(&mut self) -> Token {
        let t = self.raw().clone();
        if self.pos < self.toks.len() - 1 {
            self.pos += 1;
        }
        t
