pub fn parse_sig(s: &str, st: &mut Store) -> Ty {
    let mut p = SigParser { toks: sig_tokens(s), pos: 0, tvars: HashMap::new(), uvars: HashMap::new(), evars: HashMap::new(), kvar: false };
