        }
        match t {
            "int" | "float" | "num" => {
                let kind = match t {
                    "int" => Kind::Int,
                    "float" => Kind::Float,
                    _ => {
                        self.kvar = true;
                        Kind::Gen(0)
                    }
                };
                let mut unit = Unit::one();
                if self.peek() == "<" {
                    self.next();
                    let mut den = false;
                    loop {
                        let u = self.next();
                        if u == ">" {
                            break;
                        }
                        if u == "/" {
                            den = true;
                            continue;
                        }
                        let name = u.trim_start_matches('\'').to_string();
                        let n = self.uvars.len();
                        let i = *self.uvars.entry(name).or_insert(n);
                        let mut e = 1;
                        if self.peek() == "^" {
                            self.next();
                            e = self.next().parse().unwrap();
                        }
                        if den {
                            e = -e;
                        }
                        unit = unit.mul(&Unit::atom(UAtom::Gen(i)).pow(e));
                    }
                }
                Ty::Num(kind, unit)
