type R<T> = Result<T, Diag>;

pub enum UErr {
    Mismatch(Ty, Ty),
    Occurs(Ty, Ty),
    Effect,
    /// a type that must be ordered holds this function type
    NotOrdered(Ty),
}

fn builtin_type(name: &str) -> Option<usize> {
    Some(match name {
        "int" | "float" | "bool" | "string" | "unit" => 0,
        "List" | "Set" | "Seq" | "Option" | "Async" | "Decoder" => 1,
        "Map" | "Result" => 2,
        "Exception" => 0,
        _ => return None,
    })
}

